INSERT INTO Review VALUES('f108255f-b748-4e2f-be61-edc1676287d6','c59c3d90-b6ad-43bd-8652-73bfdce05d5b','A gem within the sacred valley! A lovely restaurant which offers pan-Asian cuisine. The staff were friendly and attentive & the service was efficient. Food is absolutely delicious and some of the best (if not the best) we had on our trip! Thank you guys','Thomas Hale',5);
