INSERT INTO Review VALUES('dd4df030-1d92-4042-af13-29851f036f1e','8d2e78ce-8304-448a-8ed4-1540ece5e338','Best burgers and wraps I’ve had in all of Peru. Staff is friendly and speak both Spanish and English.','Ryan Fallon',5);
INSERT INTO Review VALUES('8ae6394b-e923-4908-9d40-a12f20ac3b87','8d2e78ce-8304-448a-8ed4-1540ece5e338','Amazing five star service both for supper and breakfast. 10/10 would recommend!!!','David Nantel',5);
INSERT INTO Review VALUES('d4899802-557b-49f5-932e-6972395dce7d','8d2e78ce-8304-448a-8ed4-1540ece5e338','Amazing service at Maria Milanesa. Owner went above and beyond to provide us 5 stars service. Food was delicious and well priced. He even kept something we had lost the day before so we could get it in the morning. It gave us a chance to get a delicious breakfast on top !','Ir is',5);
INSERT INTO Review VALUES('a343a55a-f1af-4545-8566-0de6c5bf84a8','1d47258d-44ef-48af-ba78-f643d19f254e','Wir haben ein Wochenende in Urubamba verbracht, und weil es uns so gut gefallen hat, sind wir drei Mal hierher gekommen. Man fühlt sich wie in einer Oase, das Café ist gemütlich eingerichtet. Der Inhaber ist super nett, das Essen ist liebevoll zubereitet und qualitativ hochwertig. Kann ich nur empfehlen!','Alexander Ammann',5);
INSERT INTO Review VALUES('471f8b71-4440-4355-a4e6-c5c4cf5d0aaa','1d47258d-44ef-48af-ba78-f643d19f254e','Estoy tan feliz de poder disfrutar de un espacio así de hermoso, una joyita cálida y acogedora en el corazón de Urubamba. La comida es deliciosa, se nota el amor en cada detalle, la atención es excelente… No puedo esperar a probar toda la carta! 100% recomendado','Melissa Abrill',5);
INSERT INTO Review VALUES('0abff372-41d4-4290-84d7-85ecfd53cdd6','1d47258d-44ef-48af-ba78-f643d19f254e','Amamos 🫶🫶 desayunos deliciosos con muy buen café, ademas de que son muy amables, lo recomiendo ampliamente','José Eduardo Gómez',5);
INSERT INTO Review VALUES('5abe462b-c5a1-48d8-bed8-cb63de331710','331a94ad-e4ab-4b30-ba50-762bd71f6463','Muy mala organizacion, sin bandejas, sin comidas, tardando mucho tiempo,...ha sido muy frustrante esperar para volver a la mesa 20-25''. Deberánekorar mucho!','Angeles Martin',1);
INSERT INTO Review VALUES('0c28d84d-de3d-413b-90b8-36a0fe28a127','331a94ad-e4ab-4b30-ba50-762bd71f6463','La entrada era un poco escondida, son pet friendly lo cual fue muy importante para escoger el lugar, nos brindamos una tarifa de 55 soles por persona, muchos de los platos estuvieron buenos, lo único q no había mucha variedad, las señoritas q atendían eran un poco distraídas.','Luciana Cabrera Galdo',4);
INSERT INTO Review VALUES('c8c1465d-1cd6-4e2b-b22e-5b970b6102d3','331a94ad-e4ab-4b30-ba50-762bd71f6463','Tengan cuidado cuando te digan el precio por internet ya que al llegar al restaurant va a depender de quien te atienda si te respetan el precio que te dijeron  por internet y si no erees peruano te suben el precio, lo que me parece injusto ya que el servicio es el mismo, en fin … el personal que atiende deja mucho que desear y en redes sociales te entregan falsa informacion (me imagino que es para captar clientes)','gonzalo sepulveda',1);
INSERT INTO Review VALUES('94db50d8-fcb2-49e3-ad51-2b7cd6732d83','8aa3ad87-834c-45df-976c-48e8872d0849',replace('Excelente servicio y ambiente familiar\nTodo caliente y con buena sazón.\nSuficiente el bufett, comida variada\nCostos accesibles.','\n',char(10)),'Marycarmen hdez',5);
INSERT INTO Review VALUES('ce001b30-0cb0-418e-807e-2e98a6b3098b','8aa3ad87-834c-45df-976c-48e8872d0849','Muy rica comida y excelente servicio. Nos tocaron música que pedimos y muy amables todos!','Chelsea Rodríguez',5);
INSERT INTO Review VALUES('92c2c025-8208-4c2c-9c5d-6b879bcffd26','8aa3ad87-834c-45df-976c-48e8872d0849','Para primera ver que vine fue muy excelente y es una bonita experiencia','Isaura lisbeth Suca martiarena',5);
INSERT INTO Review VALUES('c63b7fc8-f3db-4dcd-aafa-0d04c2ade4ff','1b77e227-fb3c-4d64-9073-ab039f7a5e6f',replace('La experiencia en este restaurante fue excelente. La comida estaba deliciosa y se notaba la calidad de los ingredientes. Además, quiero destacar especialmente a Javier, el camarero que nos atendió: fue muy competente, amable y atento en todo momento. Se aseguró de que no nos faltara nada y nos hizo sentir muy bien cuidados durante toda la visita.\n\nTambién me encanta su jardín con productos orgánicos, que le da un toque especial y auténtico al lugar. Sin duda, volveré.','\n',char(10)),'The Travelling Onion',5);
INSERT INTO Review VALUES('6caba547-2471-4bf7-8413-07542d9efbac','1b77e227-fb3c-4d64-9073-ab039f7a5e6f',replace('Me encantó el ambiente, el servicio, el paisaje y la comida\nLinda experiencia','\n',char(10)),'El Blog del Bienestar',4);
INSERT INTO Review VALUES('35fb04ae-b38c-4dee-b5d1-c2c5a087601f','1b77e227-fb3c-4d64-9073-ab039f7a5e6f','Rarely do you find a place where the food is as breathtaking as the setting. Every dish felt like a tribute to the region, and the wine list offered some truly delicious local and regional finds. The staff went above and beyond to make us feel at home. If you appreciate great service and a beautiful atmosphere, do not miss this gem!','Sam',5);
INSERT INTO Review VALUES('27b86d33-0238-447c-ab61-9cd6b75c04f0','205e447d-5040-434e-9c81-f598a3fe9eb4','All the way from Chicago Illinois and this restaurant meets the expectations of a person who has developed great taste.  Thank you for your hospitality and attention to our needs.','Renee Bryant',5);
INSERT INTO Review VALUES('b2216198-3614-4aef-b1fa-55aa43ac8db6','205e447d-5040-434e-9c81-f598a3fe9eb4','Excelente atendimento, todos muito atenciosos e a comida é  excelente.','Rodrigo dos Santos Pifano',5);
INSERT INTO Review VALUES('19f746a3-b65a-4924-8ae3-c3e5a5fbd629','bffba93d-6957-4970-a816-5d8a8bc4890f','Hemos ido dos veces a este restaurante, la primera vez para celebrar San Valentín y nuestro aniversario de matrimonio, y la segunda para el cumpleaños de mi esposa. En ambas ocasiones, todo fue perfecto. El servicio es realmente excelente, el ambiente es magnífico y el personal es extremadamente amable. La comida es de altísima calidad, realmente representa lo mejor de la gastronomía. Sin duda, una experiencia excepcional.','pierre Amourette',5);
INSERT INTO Review VALUES('8384e8eb-3c16-4f12-9f09-c1be4ab2c445','bffba93d-6957-4970-a816-5d8a8bc4890f',replace('🍽️✨ Reseña del Restaurante Hawa – Hotel Tambo del Inka, Urubamba\n\nMi experiencia en el Restaurante Hawa del Hotel Tambo del Inka fue absolutamente excepcional. Desde el primer momento en que ingresas al restaurante, te envuelve un ambiente elegante y acogedor, con una decoración que combina a la perfección lo contemporáneo con detalles inspirados en la cultura andina. Las grandes ventanas ofrecen una vista encantadora a los jardines y al río, creando un entorno tranquilo y armonioso que hace que cada comida sea una experiencia sensorial completa.\n\nEl servicio es impecable. Todo el personal demuestra una amabilidad genuina y un profesionalismo admirable. Están siempre atentos a cada detalle, explican los platos con entusiasmo y te hacen sentir como en casa, pero con el trato de un restaurante de categoría internacional.\n\nLa gastronomía del Hawa es un verdadero homenaje a los sabores del Perú. Cada plato refleja la riqueza del Valle Sagrado con productos locales y frescos, cuidadosamente seleccionados y presentados con un toque gourmet. La fusión de ingredientes andinos con técnicas modernas da como resultado una experiencia culinaria que deleita tanto al paladar como a la vista.\n\nProbamos varios platos y todos fueron memorables. El cuy confitado y la trucha del Valle fueron espectaculares, con sabores equilibrados y presentaciones impecables. Las entradas con quinua y maíz destacaron por su originalidad, y los postres —especialmente el de chocolate con cacao peruano— fueron el cierre perfecto para una cena inolvidable.\n\nLa carta de vinos y cócteles complementa de manera excelente la propuesta gastronómica, con opciones seleccionadas para realzar los sabores de cada plato. Además, el desayuno buffet que se ofrece en el mismo restaurante es de otro nivel: una variedad impresionante de productos locales, panes artesanales, frutas frescas, jugos naturales y estaciones donde todo se prepara al momento.\n\nEn definitiva, el Restaurante Hawa es mucho más que un lugar para comer: es una experiencia culinaria de lujo que conecta los sentidos con la esencia del Valle Sagrado. Perfecto para disfrutar en pareja, en familia o incluso para celebrar una ocasión especial.\n\nRecomiendo este restaurante sin dudarlo. Es, sin exagerar, uno de los mejores del Cusco y del Perú, y una visita obligada para quienes buscan disfrutar de la gastronomía peruana con elegancia, autenticidad y calidez.','\n',char(10)),'El rey de la alegría',5);
INSERT INTO Review VALUES('f407bda1-ca1e-4a48-91a4-cf33b4029a18','bffba93d-6957-4970-a816-5d8a8bc4890f','Great restaurant with so many delicious options especially for vegetarians!','Stean Hausle',5);
INSERT INTO Review VALUES('84193ba2-43d7-4725-88db-7e2631245efe','65ea3319-2b51-4067-b431-8d556217537d',replace('Eapectacular comida de autor. Cada plato con un sabor diferente, pero muy especial.\nSúper recomendado 💖','\n',char(10)),'Claudia ospina',5);
INSERT INTO Review VALUES('5cf035af-20dc-4d1b-b51c-ab1224672c66','65ea3319-2b51-4067-b431-8d556217537d','Eduardo is a very accomplished chef. He cooked in Asia extensively, particularly Thailand, and therefore has many dishes influenced by that area. He is also a very engaging and charismatic man. His staff was also very friendly and informative. I would strongly recommend that anyone spending any time in Urubamba give this restaurant a try!','Matt Knight',5);
INSERT INTO Review VALUES('4fd13b18-6f0c-4f2a-9e36-ff00f417d916','65ea3319-2b51-4067-b431-8d556217537d','From the moment we walked in, Owner/Chef Eduardo made this meal unforgettable. He didn’t just take our order—he genuinely engaged with us, explaining each dish, offering thoughtful suggestions, and sharing his passion for the food he creates. The cuisine itself is a masterfully balanced fusion of Peruvian, Asian, and world flavors, each plate both visually stunning and delicious. But what really stood out was Eduardo’s hospitality. He brought out little appetizers on his own, sat at our table, and created an atmosphere that felt more like dining with a friend than at a restaurant. The food was exceptional, the atmosphere was warm and welcoming, and Eduardo’s care elevated the entire experience. If you’re in Urubamba, don’t miss Kampu. This is the kind of place and the kind of chef that reminds you why dining out matters.​​​','Eric Ervin',5);
INSERT INTO Review VALUES('33bc9062-a8f9-4320-aa92-76f1b2e25370','003f91f8-f77e-4c73-9bef-4a7817e34747','2 friends and I ate here: 1 vegetarian, 1 gluten-free, 1 everything. All of us left full and happy! Very reasonably priced. Great staff!','Starr',5);
INSERT INTO Review VALUES('dc44040b-ef38-497a-86fc-e9be7b82d0ef','003f91f8-f77e-4c73-9bef-4a7817e34747',replace('The hamburger 🍔 that I ordered was good and juicy, the french fries were good as well.\nAccording to my brother the lasagna was one of the best he has eaten. My mom ordered the same lasagna and ate the whole thing.\nThe service was great as well.','\n',char(10)),'Ayana',5);
INSERT INTO Review VALUES('e10f034a-c93e-4729-ba2e-d1335b56d280','003f91f8-f77e-4c73-9bef-4a7817e34747','Awesome experience, really delicious food','Dillon Simpson',5);
INSERT INTO Review VALUES('1b1b90cc-13fc-4a25-9e0a-239f4df651e4','b42a6970-c8b0-4a10-9231-e5893d26d151','Es un buen restaurante para grupos de viajeros...pero un servicio dirigido para masas .','Monica Isola',3);
INSERT INTO Review VALUES('5c0d6aae-9ac4-4ec7-b5d8-4e5d9021cb69','b42a6970-c8b0-4a10-9231-e5893d26d151','7 человек из группы поймали отравление после обеда в этом заведении. Это единственное место, где мы все вместе ели, поэтому сомнений быть не может :((','Павел Тур',1);
INSERT INTO Review VALUES('4ffcd6bf-4805-4009-9198-6c53534f4789','b42a6970-c8b0-4a10-9231-e5893d26d151',replace('More like a tourist trap. Not authentic peruvian food. Expensive for the buffet options.\nThe place it self is beautiful.','\n',char(10)),'Gustavo Ramos',3);
