INSERT INTO Review VALUES('46b18d40-fa04-4e29-ab02-bb2bde622729','1138e1c3-4f26-4c27-8af7-7e3ec213b67a','Heerlijk eten, ook vegan!, in een gezellige tuin. Vriendelijke bediening en snelle service! Aanrader!','Miranda Rijkers',5);
