INSERT INTO Review VALUES('0d99d028-1873-4b73-b3e8-3cba2228b5ea','6a4deb9e-c230-4b15-b660-c18bc443623d',replace('Comida Fantástica!\nAtendimento fabuloso\nEstivemos em outros restaurantes da cidade, mas a qualidade dos pratos daqui são incomparáveis!\n\nFantastic food!\nFabulous service!\nWe''ve been to other restaurants in the city, but the quality of the dishes here is unmatched!\n\n¡Comida fantástica!\n¡Servicio fabuloso!\nHemos estado en otros restaurantes de la ciudad, ¡pero la calidad de los platos aquí es inigualable!','\n',char(10)),'FABIO LONGO',5);
INSERT INTO Review VALUES('94c99b81-ef2f-47d2-81d5-9dac5e633945','6a4deb9e-c230-4b15-b660-c18bc443623d','Comida excelente la atención igual!! El ambiente es muy verde rustico.','SOPHIE BEAUD BERGER',5);
INSERT INTO Review VALUES('7ed7262b-32bf-4933-a40e-52cb7f9e8b26','6a4deb9e-c230-4b15-b660-c18bc443623d','Lugar acogedor, la comida 10 de 10, la atención excelente, volvería de todas maneras.','Adriana Mendoza Gil',5);
