INSERT INTO Review VALUES('058ce09f-3655-4c53-b923-f0086f363fc0','ae471886-ff03-4e6a-ba18-c5080384b9b1','es bueno','rayn balladares',5);
INSERT INTO Review VALUES('fbb68710-6732-409d-ba19-14a48100de19','6870f345-f220-4dc7-bb6f-fa5ef2d9ed8b','Great guided tour in English from Ollantaytambo with Luis to see Maras/Moray/Chinchero. Reasonably priced. Very thorough and informative and he took great photos as well!','Adi',5);
INSERT INTO Review VALUES('97419bb5-81cf-4fce-8bc1-0406817cc072','6870f345-f220-4dc7-bb6f-fa5ef2d9ed8b',replace('Tuvimos una experiencia increíble con Luis Alberto. Muy amable, paciente y con muchísimo conocimiento.\nNos acompañó en Ollantaytambo, Maras, Moray y Chinchero y en cada lugar nos dio detalles que no hubiéramos entendido solos.\n\nEstamos muy felicez de escojerlo a el , 100% recomendado!!','\n',char(10)),'E L',5);
INSERT INTO Review VALUES('4501e413-30eb-4406-9930-c01d310c0a6e','6870f345-f220-4dc7-bb6f-fa5ef2d9ed8b','Luis Alberto es un guía increíble. Súper paciente, explica todo con mucha calma y se nota que realmente le apasiona lo que hace. Gracias a él entendimos mucho mejor Ollantaytambo, Moray y Chinchero. 100% recomendado.','Harold Lopez',5);
INSERT INTO Review VALUES('7c6e6d8d-7384-42a5-adc4-96117148bff7','802f6501-a1a5-4b48-9c0d-6cdc0e6e9e5e','Geweldige ervaring. Octavio nam ons mee naar de uiterste uithoek van de vallei, met voorop een horde lama’s. Boven hebben we traditioneel gegeten met bewoners en zijn familie. Prachtig om mee te maken en de schoonheid van de natuur en het leven te ervaren.','Nadal Jongeneel',5);
INSERT INTO Review VALUES('1bb9b9f5-7db7-4b59-95ee-09ffcef50b6d','802f6501-a1a5-4b48-9c0d-6cdc0e6e9e5e','Hiking with llamas in the highlands, interact with local communities is what you’d like to do!, this Lares trek is a must-do! Whether you’re an avid trekker or just looking for an unforgettable experience and feel a profound sense of connection with nature, as well as the beauty of our world. don’t hesitate to include this gem on your list! You won’t regret it! 🙌','Gozguan Puma Quelka',5);
INSERT INTO Review VALUES('05c74a62-23ab-4e19-8a3d-57c40947d6fc','802f6501-a1a5-4b48-9c0d-6cdc0e6e9e5e','Servicio recomendado100%','zory',5);
INSERT INTO Review VALUES('bc8e36f5-c14a-4aa1-a788-344a63aaa373','1f545e1c-3e80-4a29-b48a-f3ae17b47a0d',replace('We went on a 4 day Inca tour with Qhapaqnan and they were phenomenal. We couldn’t have asked for a better experience. Our tour guide John took very good care of us, was extremely knowledgeable and fun to hang out with :)\n\nThe food was phenomenal! Every day we were so excited to have lunch / dinner and it blew us away every day. Some of the best meals I’ve had in my life on the side of a mountain. Incredible.\n\nThe porters were professional and quick, tents and food were ready when we came to the campsite and they were very nice.\n\nOverall highly recommend!','\n',char(10)),'Stephanie',5);
INSERT INTO Review VALUES('248d5fa0-1ab1-450f-aa00-79b0f6b7b724','39d21f05-7a0d-4a1f-b265-c8e64c39f69b','Excelente paseo en cuatrimotos','Jorge Torres',5);
INSERT INTO Review VALUES('85566f67-36b0-4346-8f04-69e3aa99da33','39d21f05-7a0d-4a1f-b265-c8e64c39f69b','El guiado para usar las cuatrimotos fue muy útil.','Jhonatan Soto',5);
INSERT INTO Review VALUES('d4835fd9-7c43-456d-bd95-1da70752dc68','32bff901-17ed-42b4-bc32-c49a6cccd2db','100% recomendado, el personal es muy amable y siempre está atento.','Susy Orozco Escarsina',5);
INSERT INTO Review VALUES('598a1041-a0d5-4193-b8e1-6f3456ed4e74','32bff901-17ed-42b4-bc32-c49a6cccd2db',replace('We rented 2 bikes for the day to explore maras, salt mines and moray. We tried many places and they couldn’t help (we booked the day before) but Bull House came through, one large Trek hardtail and one small Trek Hardtail for my partner. Amazing communication. They even picked us up with both bikes loaded, drove us to get some more cash for entrance to Moray, and then drove us up to the start at Moray. (This is additional charge if you want the drive up, highly recommended as it’s a few hours cycle if not!) We then we set off on our own. They provided maps, advice and answered any questions we had. The bikes were great, they were great and I would recommend to anyone who wants to rent bikes in Urubamba or Sacred valley. We even got a puncture and they came out to fix, they had to drive an hour round trip to get to us! Amazing people !\n\nDon’t hesitate just book it, way better way to explore than getting a bus/ tour, far more fun and there some great trails, some even with berms and jumps on the way down!\n\nIn total we paid 260 soles for the day for both bikes and the drive up to moray.\n\nBike rental for Sacred valley = Bull house 🔥\n\nThey are legends❤️','\n',char(10)),'William Stephens',5);
INSERT INTO Review VALUES('4ab20a9d-860e-40f7-8f5a-85a1fa6f437c','32bff901-17ed-42b4-bc32-c49a6cccd2db','Mi experiencia fue increíble, brindan la atención y amabilidad en todo momento haciendo que mi viaje fuera inolvidable. La comida en su restaurante fue la mejor que probé en todo mi viaje en Perú. Volvería con ellos sin pensarlo!','Jackelyn Leyva',5);
INSERT INTO Review VALUES('7ab2b072-1d21-4a8e-b263-89d2da38aca0','cbc1bd29-dea0-4bc6-817d-c0936820b1fc',replace('La atención del Joven julian, fue de lo mejor A1, recomendado para todos y su flota de autos bonito, limpio y él personal qué maneja super educados.\n❤️1','\n',char(10)),'Mario Aguilar',5);
INSERT INTO Review VALUES('f34545b6-6118-4191-a365-6ac957bc2794','cbc1bd29-dea0-4bc6-817d-c0936820b1fc','¡Excelente servicio en Cusco! Saul fue súper confiable y se adaptó a todo lo que necesitábamos. Fue muy amable con nosotros y el precio fue bastante justo. ¡Totalmente recomendado!','Saatvik Jindal',5);
INSERT INTO Review VALUES('59887973-6480-414a-9d48-5e5acd065c6e','cbc1bd29-dea0-4bc6-817d-c0936820b1fc','Muy buen servicio','Pablo Sinchi puma',5);
INSERT INTO Review VALUES('3c2157c0-8ae8-4131-a232-19d33eafe892','bfcc4f08-b7af-4fbb-a875-be22e6a4a841',replace('Ho noleggiato qui una bici e il servizio è stato davvero estremamente gentile. La bici era in buono stato e mi hanno dato anche il casco. Hanno anche dei consigli su che giri fare. Altamente raccomandato.\nHo pagato 40 soles per mezza giornata (4/5 ore circa).','\n',char(10)),'Alice Beatrizotti',5);
INSERT INTO Review VALUES('eddc7b22-9293-4f0b-a627-59d323769013','bfcc4f08-b7af-4fbb-a875-be22e6a4a841','Buen servicio para prestar bicis con DNI a 70 el día, incluye casco','Percy M.',5);
INSERT INTO Review VALUES('25c307e3-c795-49aa-9e1a-ed4ca3a6bafe','bfcc4f08-b7af-4fbb-a875-be22e6a4a841','Una experiencia de cliente fantástica, las bicis que nos facilitaron estaban en perfecto estado y son muy apropiadas para las rutas que se pueden hacer por la zona.','Yûr',5);
INSERT INTO Review VALUES('24d24e9c-8b06-463d-b9bf-f79000599ee5','7964a40e-16f1-4e44-8da2-d41ee8689ba3',replace('Our guide Auki and our driver Abelino were absolutely wonderful!!!\nWe asked many questions about Inca history and heritage, and every time, Auki gave us incredibly detailed and thoughtful explanations. Throughout the Sacred Valley, he helped us understand the historical symbols and deeper meanings behind each site, which made the tour truly meaningful and enriching.\nAuki and Abelino were both very attentive and made sure we were comfortable and relaxed from start to finish.\n\nThanks to their care and professionalism, we were able to enjoy the entire tour with ease and genuine joy :)','\n',char(10)),'A W',5);
INSERT INTO Review VALUES('345609d5-2587-49cb-ab79-e6c0cd2393ec','7964a40e-16f1-4e44-8da2-d41ee8689ba3',replace('The crew at Peru Alive really cared about giving us the best experience possible! Our trip was magical and awesome. They expertly avoided crowds and made us feel like part of their families! Their local knowledge and life experience was priceless in bringing us deep insight into the history, culture, people, and places that we got to see and experience!\nThey get my highest recommendation!\nBucket list experience all the way through!\nRich Lapp','\n',char(10)),'Rich Lapp',5);
INSERT INTO Review VALUES('8644bc02-9ef4-4e3b-bbe6-f3673ef5d5a7','7964a40e-16f1-4e44-8da2-d41ee8689ba3','I had an incredible experience with Peru Alive! Wilbert, who is one of the best guides I’ve ever had on my many journeys, shared the deep wisdom of culture, traditions, landscapes and history he has gained through a lifetime of experience. It allowed me to do far more than just observe the beauty and wonder that I witnessed everywhere we went. Through Wilbert,  I came to see the living connection between the deep past of the Inca, and the modern Quechua people, through their ongoing worship of Pachamama (Mother Earth), devotion to family and community, and generosity of spirit. I feel so fortunate to have met Wilbert and his family, and am already looking forward to the day that our paths cross again','Jason Bedford',5);
INSERT INTO Review VALUES('6ab5defc-4405-4c6c-8a36-e85371d9c9ce','ca905e7f-59e8-4250-bb5c-40c50590156b','Guilana help us plan the trip of my dreams. What an amazing experience with an amazing team!','Carrie Sellers',5);
INSERT INTO Review VALUES('2f2a31e1-3aa4-47b5-8305-d890a7d5aa2e','ca905e7f-59e8-4250-bb5c-40c50590156b','Santu was amazing!  We did a day tour and a 4 day inca trail trek with them and everything was flawless.  I love that they are local and take good care of their people (tour guide and porters). Would definitely recommend them over the bigger companies that are easier to find on the internet.','mfa330',5);
INSERT INTO Review VALUES('a20e7297-ae20-4e6a-894f-9815c8e99370','ca905e7f-59e8-4250-bb5c-40c50590156b','I had a once in a lifetime experience with all employees involved. My driver Victor went out of his way to provide for a quick arrival to the train station while giving me a tour of the area. All while taking a slightly longer route to ensure our safe arrival despite the rain. Arriving at Machu Picchu Miara met me with a warm smile and gave me an amazing tour of the beautiful culture and city of Machu Picchu. I learned facts that I would never forget about such a beautiful place. Always giving me her full attention and taking some of the most breathtaking pictures that allowed my family to feel like they were there with me. Lastly, Jesus Manuel went above and beyond spending a considerable amount of time with me taking me to different archeological sites and the textile mills. This was at no additional charge and came out of the kindness of his heart to make sure I had an unforgettable 21st birthday. Santu Tours will give you an unforgettable adventure if that is what you seek. They will ensure your experience in Peru is a beautiful one. Thank you!','Diego Alexis',5);
INSERT INTO Review VALUES('0320131f-3981-4fc7-8b11-9b75da6b6c52','ea734859-4036-42b4-83b2-5407f7a62fe7','Excelente servicio, puntualidad excepcional, vehículo amplio y limpio, lo utilizamos todos los días en nuestro periplo por El Valle Sagrado y Cuzco. Y lo mejor su driver y guía Cristian Cruz grandioso ser humano, conocedor de su trabajo y de la historia de su pueblo. Recomiendo a esta empresa y a su personal.','HAROLD RESTREPO',5);
INSERT INTO Review VALUES('9c5236ab-fe84-4896-a878-60ddb3424cc7','ea734859-4036-42b4-83b2-5407f7a62fe7','Pésimo atendimento.','marleny pantigoso cjuiro',2);
INSERT INTO Review VALUES('ec8ca69c-bb3d-4097-9a17-6f2abe896556','ea734859-4036-42b4-83b2-5407f7a62fe7',replace('Buen transporte, mini van cómoda, amplia, con aire acondicionado si tienen mucho calor o con calefacción si tienen mucho frío.\nChofer prudente y muy puntual.\nExcelente servicio.','\n',char(10)),'Grishell Yañez',5);
INSERT INTO Review VALUES('960b2cfb-dac3-484f-9f1b-40e2c8e16b6f','d6bd8bdc-2741-437e-8992-63906410ad62','We did a private small group tour to the sacred valley with this company. The driver, with a clean van, and guide was courteous, knowledgeable and professional. We thoroughly enjoyed and appreciated the full day. Highly recommend this tour company.','Tina W',5);
INSERT INTO Review VALUES('80463cb0-7348-4ba6-b2ff-7b670fd9afb1','d6bd8bdc-2741-437e-8992-63906410ad62','Great service and guide. Very comprehensive.','Ron Laker',5);
INSERT INTO Review VALUES('d3b1fed9-6e42-4fee-86de-a55be1c17a7f','d6bd8bdc-2741-437e-8992-63906410ad62','Tour do vale sagrado muito bom! Adorei, recomendo!','Carolina Banfield',5);
INSERT INTO Review VALUES('1901743d-fda9-4ce3-bc5d-47d9b458b0a3','eeb6f7d3-7d08-4127-930d-bd9e181d7da7','My husband booked this place for us, as a special surprise for my birthday.  He told the restaurant staff it was my birthday and they decorated my piece  of chocolate  cake and put a candle in it,lite brought it to the table and sang to me!','Kathleen Bradshaw',5);
INSERT INTO Review VALUES('270bbf10-6765-4883-b7c8-5ab979405aef','dbd19f6f-d04d-411a-8d3b-2ca139b9eaa8','A slice of paradise. Epic mountain views and incredible food. Lovely birds. Attentive, energetic and hospitable professionals work here. Highly recommend!','Andrew Saluke',5);
INSERT INTO Review VALUES('6d437e83-9676-4477-803c-cfd65f9a44d1','dbd19f6f-d04d-411a-8d3b-2ca139b9eaa8',replace('Overall Impression: Sierra Sacred Valley is a stunning boutique property that strikes a perfect balance between high-end luxury and authentic Andean charm. With breathtaking mountain views and a resident group of 5 or 6 alpacas roaming the grounds, it offers a serene atmosphere that is ideal for decompression at either the start or end of a Peruvian itinerary.\nService & Dining\nThe service here is truly first-class—attentive without being intrusive. Due to the resort''s remote and peaceful location, most meals are enjoyed at the on-site restaurant. Fortunately, the culinary program is exceptional; the food is flavorful, beautifully presented, and easily rivals top-tier urban establishments.\nThe Huchuy Qosqo Trek: A Hidden Gem\nOne of the standout features of this resort is their curated tour programming. I highly recommend the Huchuy Qosqo Trek. It is a roughly 10km hike along an original Inca route—a rare find that I didn''t see offered elsewhere. For capable hikers, it is a special, immersive experience that feels far removed from the typical tourist trails.\nStrategic Logistics for Machu Picchu\nThe resort is excellently positioned for those planning a visit to Machu Picchu:\n• The Route: It is a quick and easy transfer to Ollantaytambo, where you can catch a direct train. This is a much more efficient strategy than traveling from Cusco, which results in a significantly longer and more exhausting day.\n• The Train Experience: I took the First Class service on the way up to enjoy the views and opted for the Prime train for the return. Since it’s dark on the way back anyway, the Prime service is a smart way to manage costs without sacrificing comfort.\nFinal Verdict\nWhile the property is a premium investment, the quality of the experience justifies the price tag. It is a world-class spot to relax and find your footing in the valley. Highly recommended.','\n',char(10)),'Patrick L',5);
INSERT INTO Review VALUES('702a7f8f-d144-4fec-aa76-dbcd30e21df8','2957f4fe-7782-4946-9e34-eed05959a0dd',replace('Lo recomiendo, la atención es muy buena, es seguro las habitaciones cómodas\n10 de 10 , si buscas un lugar cómodo económico y seguro.\nGraciass\nMe voy contento 😃','\n',char(10)),'Marisol CCC',5);
INSERT INTO Review VALUES('33f13b15-cb00-4fa6-a1c1-5a15b6305401','2957f4fe-7782-4946-9e34-eed05959a0dd','Me encanto baños limpios todo ordenado camas limpias y sin pelos y el dueño es mi tío le doy 5','Uziel Torres',5);
INSERT INTO Review VALUES('9a7173ef-8455-49ad-b335-e85c0318c7f9','a3a6afcc-9188-41b4-aa65-8feebe856d34','Insane experience, the “pachamanca”. Walking with Alpaca’s and the food was amazing!','Bo Bosman',5);
INSERT INTO Review VALUES('b4945a9a-eede-4aaf-90cd-baced0afc30e','a3a6afcc-9188-41b4-aa65-8feebe856d34','Amazing stay and experience ! The room was clean with amazing view on the sacred valley , the dinner was also delicious . You can do many activities with the owner , we chose the walk to an archeological site with Alpacas . Was truly beautiful ! I recommend this stay!','Elisabetta Niero',5);
INSERT INTO Review VALUES('4d6d41eb-4373-4171-98e6-5a306282f74f','a3a6afcc-9188-41b4-aa65-8feebe856d34','An absolutely incredible experience. Words can hardly capture how exceptional our time at this place was.','francesco',5);
INSERT INTO Review VALUES('f7a59030-0220-4105-a0ae-2a62a9ccb4d2','2b60e5e6-0e59-4fc3-816e-b2054b7d9afd','L’expérience est incroyable ! Vous êtes en haut de la montagne, avec vue sur la vallée. Les dômes sont immenses, il fait assez chaud grâce au chauffage présent, bonne douche chaude, bonne wifi. L’hotel propose également un restaurant sur place.','Maxime',5);
INSERT INTO Review VALUES('ebc0747c-bc7c-4513-9feb-60587cfc4eb2','2b60e5e6-0e59-4fc3-816e-b2054b7d9afd','Notre sejour fut un rêve de toute beauté. Notre dome avait une vue incroyable sur la vallée. Le service est impeccable, nous adoré profiter du jacuzzi privé et se reveiller avec les lamas lors du petit déjeuner.','Pauline',5);
INSERT INTO Review VALUES('0b2c888d-d9c9-45a7-92ad-e3babdcde1e1','2b60e5e6-0e59-4fc3-816e-b2054b7d9afd','I stayed here for 3 days last week and I’m so glad we chose this property. Spacious domes, great service and facilities, unmatched views. We felt this might have been the most unique and enjoyable stay out of all our vacations.','Mayank Agrawal',5);
INSERT INTO Review VALUES('6ef4a350-b468-44fb-9810-53f4649e68e8','06333e7b-5a45-41b3-8eba-192999a32ea9','Es un lugar hermoso y la atención de primera. Hay una sección que fue el claustro y celdas de las monjas de Sta Catalina de Siena las cuales tienen en un lado de la puerta un texto alusivo a la hermana que lo habitó.','Marien Vega',5);
INSERT INTO Review VALUES('f5c7e9b3-cfcd-4c8f-9b56-499dbc13489c','b6160889-82bf-4005-86a6-39b9e48592ab','Konaklama için doğanın içinde mükemmel bir otel. Harika bir bahçesi var.','Levent Cagatay',5);
INSERT INTO Review VALUES('be5e75d8-2bda-428d-9fbc-39f7958a7ff0','32fd02de-17b0-4c6c-adb6-e6b1c1d4c723',replace('“Experiencia maravillosa en Inkaterra Hacienda Urubamba.\nNuestra estancia fue simplemente excepcional. El hotel es absolutamente hermoso, rodeado de naturaleza y con un ambiente muy tranquilo que permite desconectar y disfrutar del Valle Sagrado.\n\nLas habitaciones son amplias, muy cómodas y perfectamente cuidadas, con una decoración elegante que combina muy bien con el estilo andino del lugar. Todo estaba impecable y pensado para que la estancia sea realmente relajante.\n\nEl entorno del hotel es impresionante: jardines muy bien mantenidos, vistas increíbles a las montañas y una atmósfera muy especial que transmite paz desde el primer momento. Es un lugar perfecto para descansar y disfrutar del paisaje.\n\nEl personal merece una mención especial. Todo el staff fue extremadamente amable, atento y profesional, siempre dispuesto a ayudar y a hacer que nuestra experiencia fuera aún mejor.\n\nSin duda, un lugar precioso y una experiencia memorable en el Valle Sagrado. Lo recomendamos totalmente y volveríamos sin dudarlo.” ⭐⭐⭐⭐⭐','\n',char(10)),'MAIKO BARRETO BARBOZA',5);
INSERT INTO Review VALUES('09035305-91d9-4331-b723-8f4c4b177cc2','32fd02de-17b0-4c6c-adb6-e6b1c1d4c723','Amazing hotel! 100% recommended!','Eli PM',5);
INSERT INTO Review VALUES('afcc66dc-6e7f-40ad-a929-487778897915','32fd02de-17b0-4c6c-adb6-e6b1c1d4c723','Local perfeito, hotel maravilhoso','Bruno Jacob',5);
INSERT INTO Review VALUES('960d16a2-4b78-4721-aa0a-289610f6f6ab','d31e915e-81d6-434c-9fbd-d4fa0daeea4e','Great Place','Ale Angel',5);
INSERT INTO Review VALUES('20d4c3fc-f803-438e-9b44-822be4048d88','d31e915e-81d6-434c-9fbd-d4fa0daeea4e','It seems hard to overstate how wonderful the Explora experience. Everything is planned for you to a T. The guides carry hot soup and tea to remote hiking picnics. They tell you what to pack. We came with drinks, guides, food, all included. The food is very good and variable. The service quality is next level — thanks to everyone who made our honeymoon special.','Julia Enthoven',5);
INSERT INTO Review VALUES('c94e6168-280a-4733-830b-eca31c8bc6b8','429bb385-935a-45ef-8897-b8be403817af',replace('I don’t have many photos, but I had to leave a review because their professional handling of our 31-person group was top-tier. From the booking process to room assignments and luggage logistics, everything was smooth as silk.\n\nWhen we arrived, every room was already sorted exactly as requested, singles, doubles, kings, all assigned to the right names with receipts and paperwork ready for signature. No mess, no waiting. Even better, when we returned from an excursion from Machu Picchu, all our luggage was already organized in the lobby exactly as instructed, ready to go. For a group this size, that’s five-star service.\n\nThe rooms were quiet, and the hot water was excellent (a must!). The location is a bit away from the center, but we knew that beforehand, plus, a Tuk-Tuk only costs 5 Sol and they’re easy to find. The courtyard with alpacas is a great touch, and the staff were genuinely friendly.\n\nThe breakfast spread was huge. My only tiny suggestion? I’d love to see some sugar-free yogurt options next time. Other than that, the stay was flawless. Highly recommended!','\n',char(10)),'Pazu P',5);
INSERT INTO Review VALUES('74d2a689-fa45-4e15-8bec-c9ffbbb1d8a7','429bb385-935a-45ef-8897-b8be403817af','Precioso','Lillian Ascue',5);
INSERT INTO Review VALUES('d2a38fbb-3e12-4bf6-bbc4-8f0fdf6e0d50','676e4d0d-be34-463e-824c-ca0538a36cbe','Es un lugar arqueológico hermoso','Adriana Maria Arboleda Serna',5);
INSERT INTO Review VALUES('327dad00-4f24-480a-8e35-694af9faead6','676e4d0d-be34-463e-824c-ca0538a36cbe','Todo el mundo piensa en Machu Pichu y este valle está lleno de sitios e historias preciosas','Amparo Santamaría Ortiz',5);
INSERT INTO Review VALUES('c9907313-4b69-4b20-888a-aa11352e87b7','676e4d0d-be34-463e-824c-ca0538a36cbe',replace('Un lugar mágico. Dónde se puede apreciar el río Urubamba y sus picos nevados a la derecha. Realmente es sagrado, se sienta una agonía energética impresionante. ¿Lo recomiendo? Total! La experiencia de visitar y conocer este valle te hará crecer como persona.\n#peru #vallesagrado','\n',char(10)),'Ricardo Calle',5);
INSERT INTO Review VALUES('fc7315b4-c425-46c9-b74f-4f8703793c4d','4c5a0f0f-32fa-489b-b4ff-18044a002c00','This is the place to stay. Tip don''t buy anything from the Lama Farm tour! The hotel has three lovely ladies with all the same beautiful garments and bags in the  lobby. Beautiful big rooms and fabulous showers, friendly staff and amazing food! It''s an open air short walk to rooms if you''re that fussy 😁','AussieAL',5);
INSERT INTO Review VALUES('06f364b3-5a2b-4ae7-b7ad-8928969db01c','610f562a-100c-470e-83ee-9e86a046634a',replace('Every employee that works at the Tambo del Inka were all polite and helpful. The hotel has a nice pathway for daily walks if you don’t want to go outside.\nThe only thing that I didn’t liked was the sewage smell that happened on Wednesday night, it came from the outside 😵‍💫 I am guessing it was from the treated water used to water all the grass and plants. (That only happened on Wednesday night though.)\nThe hotel offers different type of activities, it has its own train 🚂 rail, their restaurant was good, etc. Overall a great experience.','\n',char(10)),'Ayana',5);
