INSERT INTO Review VALUES('131a612d-6630-48a7-baa6-41ccd256abbf','b0ab16db-f01c-45fd-80b1-4888aa78f78a',replace('Muchísimas gracias a Franco y a sus manos por esta experiencia thai. Un momento intenso y sanador para canalizar todo, física y mentalmente. Amé mucho su energía y su forma de abordar el masaje. Salí de su lugarcito con una paz interior bien palpable.\n\nTupananchiscama, maestro, y mucha suerte.','\n',char(10)),'om&go Studio',5);
INSERT INTO Review VALUES('ff36f91f-9b9a-46b4-a149-f42b5ca09a6d','b0ab16db-f01c-45fd-80b1-4888aa78f78a','Una experiencia muy recomendada, el masaje tailandes fue intenso, a la vez bien sensible y delicado, sentí una  diferencia bastante notoria en mi cuerpo al salir. Mucha sensibilidad y profesionalidad de su parte.','Jessica Daza',5);
INSERT INTO Review VALUES('a5bbb253-7fa7-4b48-b066-8f3a138f0d62','b0ab16db-f01c-45fd-80b1-4888aa78f78a','Tome el masaje tailandés, y debo decir que me encantó! Es una experiencia nueva y revitalizante. Si buscas un espacio para relajar, estirar cada parte de tu cuerpo , este es el indicado. La atención y trato fueron A1, Franco fue muy cordial y me explicaba en qué consistía esta técnica . Lo recomiendo totalmente.','Marion Chuquiyure',5);
INSERT INTO Review VALUES('cb7b3ddb-511b-4e24-bedf-aedb594a1037','87188d05-0eaa-47ef-bd74-964539850e70','Un buen lugar para disfrutar de sanación y relajación con técnicas combinadas tanto fisioterapeutas como naturales ☝️','Verónica Vega Centeno Bueno',5);
INSERT INTO Review VALUES('61539b95-20d7-4a78-a464-1a4d6501c076','87188d05-0eaa-47ef-bd74-964539850e70','Es war unglaublich entspannend und so schön! Ich hab mich direkt wohl gefühlt. Veronica ist eine ganz herzliche Person. Ich komme gerne wieder!','Cirella Schäfer',5);
INSERT INTO Review VALUES('132b3430-9cde-4e0d-98b0-cc84f39db15c','87188d05-0eaa-47ef-bd74-964539850e70','Veronica me atendió a finales de febrero y me ayudó muchísimo en tan sólo una sesión. La sesión energética y el masaje fueron relajantes y emocionales. Vero fué muy atenta a mis quejas de dolor y me dió estupendas recomendaciones de ejercicios que me han ayudado hasta ahora. También me dió seguimiento nutricional y terapéutico algunos días después y me aclaró cualquier duda que tenía. Se nota que en realidad le importa ayudar a los que la visitan. Les recomiendo darse la oportunidad de que ella los guíe y les ayude. Muchas gracias Vero, espero algún día poder regresar de nuevo!','BlanKiux E',5);
INSERT INTO Review VALUES('77a2e549-f428-4d38-b519-21c835c284e7','5986e1c3-003f-40de-b56b-1a379f5150c1',replace('Genial todo! Yovana me hizo un cambio de look, despues de 4 años sin tocar mi pelo, y me encantó!\n\nSuper amable, el espacio muy lindo y comodo. Hasta me invitaron una copa de vino.\n\nGracias!!!!','\n',char(10)),'Mili Centeno',5);
INSERT INTO Review VALUES('c26e5dd1-e933-4e70-bce7-f0f942176633','0e94e443-f10c-4363-990b-11a7e8897e3a',replace('When the spa comes to you!\n\nJust had the most relaxing Peruvian massage  right in my hotel room💆‍♀️✨\n\nEvery bit of stress melted away. The pressure was perfect, the atmosphere calming, and I left me feeling completely refreshed.\n\nHighly recommend if you need a reset 🙌\n\n10/10 experience','\n',char(10)),'T McGowan',5);
INSERT INTO Review VALUES('88b0dff0-bc32-4bd5-9a61-b640c23f9e89','1e39736d-dc4d-4650-ba77-90e2366361e1',replace('UNA VERDADERA Y REAL EXQUISITEZ DE SPA, DIGNO DEL MARAVILL¡LOSO HOTEL DONDE SE UBICA.\nDESTACARÍA EN ESPECIAL A MARGARITA LA FISIO CON UN 12 SOBRE 10 POR LA HABILIDAD DE SUS MANOS Y SU CORDIAL TRATO Y A ARIATN LA ENCARGADA DE RECEPCION DEL SPA CON OTRO 12 SOBORE 10, PUES LLEVA DE FORMA PERFECTA SU LABOR','\n',char(10)),'EZEQUIEL DE CASTRO ARIAS',5);
INSERT INTO Review VALUES('9240d8a7-d086-4f7e-a308-161e18bc53e1','1e39736d-dc4d-4650-ba77-90e2366361e1','Es una maravilla la comida espectacular  es muy hermoso habiente tranquilo relajante','Henry Fernando Quispe Amezquita',5);
INSERT INTO Review VALUES('7b0a5782-b8f3-4607-b209-7e043e267318','1e39736d-dc4d-4650-ba77-90e2366361e1',replace('Localizado no coração ótimo hotel Aranwa Sacred Valley que fica localizado na Antigua Hacienda Yaravilca em Urubamba, aos pés da Cordilheira Andina e aproximadamente a 43 km do Aeroporto de Cusco, as margens do Rio Vilacota,o  UNNO SPA é o primeiro centro de bem-estar e o mais completo e especializado do Peru, possui uma moderna infraestrutura equipada para oferecer diversos serviços, que unem o a tradicional sabedoria Andina e a medicina alternativa, com o que existe de mais moderno em tecnologia cosmética, prestando serviços de alta qualidade, com produtos 100% naturais.\nCercado de muito conforto e belas bela paisagens, o hóspede desfruta de várias opções de terapia, relaxamento e bem estar físico e mental, pois o local disponibiliza sessões de Pilates, Ioga, Zumba, hidratação, Shirodhara, Massagem Ayuevédica, Massagem Abhyanga, Acupuntura, Banho de Hipertermia, Câmara Hiperbárica, Oxigênio Relaxado, Massagens Oriental e Descongestionante, Ritual do Chocolate, Tratamentos Faciais, Eletroterapia, Hidroterapia, Relaxamento, Salão de Beleza e estética, com serviços de cabeleireiro, depilação, manicura, pedicura e outros.\nO único ponto negativo é que a sauna e todas as atividades do SPA são cobradas à parte das diárias, o que no meu entendimento seria desnecessário, pois a sauna e algumas comodidades consideradas mais simples, bem que poderiam estar incluídas no valor da diária, que não é baixa.','\n',char(10)),'Carlos Roberto Minossi',5);
INSERT INTO Review VALUES('dc953a40-938c-4486-b264-3050bffcf11f','63f2dcee-bf62-487a-9918-d170be894b27','Flor is the best masseuse I''ve ever had. Highly recommend!','Corinne H',5);
