INSERT INTO Review VALUES('51277d65-fc34-4234-9dcd-669e2247521d','1843dc78-b745-490f-94a9-3810c1e350f4',replace('高山病と時差ボケと、遺跡巡りの疲れで、当初予定はなかったのですが、こちらの評価が高かったので急遽予約しました。WhatsAppで1時間前に連絡したにも関わらず快く応じてくれました。インカマッサージ120ソル。カードも使えますが、現金の方がお得です。わかりにくい場所にあるのですが、場所も動画で事前に教えてくれます。\n施術は的確で気持ちが良く、終わった後特に肩が軽くなった実感がありました。もう少しスペイン語ができれば、もっとお話ししてみたかったです。ありがとうございました！','\n',char(10)),'CHIIBA',5);
