INSERT INTO Review VALUES('1fcdf285-66c4-426f-9775-0afa0f85e1f6','1eac939c-66cb-4fd1-b436-7930f71df54f','The food was super delicious , the place manager was super nice and polite, we had a very deep conversation, thank you so much!','Psyhange',5);
INSERT INTO Review VALUES('6d0241e3-802b-4ef7-ba63-bb5ec99e3ac6','1eac939c-66cb-4fd1-b436-7930f71df54f','A gem in Pisac. The food and drinks were amazing and the decor and vibe really lovely!','Val',5);
INSERT INTO Review VALUES('6483be6e-ffba-4afc-9d17-04099d7a686b','2bcefae4-ae74-41a5-9ae5-480486230bab',replace('Juste wowwww, délicieux, très belle ambiance calme, de la bonne musique de fond.\nNos deux assiettes étaient juste incroyable, en voyage depuis 8 mois autour du monde, ça a fait du bien de manger aussi bien, une très belle surprise ici à Pisac !','\n',char(10)),'Elodie',5);
INSERT INTO Review VALUES('1d44a394-51fb-475b-8ab3-b1184bde766a','2bcefae4-ae74-41a5-9ae5-480486230bab',replace('Highly creative and cute little restaurant.\nWe had an unexpectedly good time - almost fine dining vibes for some of the dishes.\n\nWe had the ceviche (experimental but great), the lake tiradito (amazing!!), and lemon cloud (super - think lemon cest meets crême brûlée).\n\nClearly a hidden jem in the sacred valley.','\n',char(10)),'Delilah c.',5);
INSERT INTO Review VALUES('d0c89427-008d-4f26-b329-35a6dac8ecbb','2bcefae4-ae74-41a5-9ae5-480486230bab','In retrospect, we should have paid attention to the little voice in our heads telling us to turn around and leave right after we had entered. The restaurant had a dark and dingy vibe, smelled a bit dank and was completely empty. The prices were well over the top (higher even than a classy place in Cusco) so we ordered the ceviche and trout main (which turned out to be very similar in nature). The fusion effort didn’t quite fly, but the fish was ample and pretty good, aside from the price gauging. The nail in the coffin for this place was the service. The chef/waiter/owner? was on speaker phone for most of our meal, so we had to listen to a combination of the shmaltzy music and his conversation as our dining backdrop. When we finished, he cleared the table and we indicated that we were complete. Instead of bringing the bill, he proceeded to go outside and start another phone conversation in the road. We waited a while, went to the bathroom etc and eventually I had to go out in the road and wave a credit card in his face to get his attention so we could pay and get out of there. He clearly knew he was out of line as he apologized, but the bad taste was already in our mouths. As it was, we spent over 100 soles to have our least favorite dining experience in the Valley. For a restaurant advertising and charging for a fabulous vibe, this is a fail.','June Adjii',3);
INSERT INTO Review VALUES('ebaaaa73-aa37-4c5c-8cdc-275b3e2223c4','5877d999-db2c-4fa1-8c7b-1bdc9997d6ff','Mala atención pésimo servicio','Manuel E.',1);
INSERT INTO Review VALUES('9e654ef1-57b7-416e-86f3-2a28bcd545c1','5877d999-db2c-4fa1-8c7b-1bdc9997d6ff','Rico y muy amables','Ricardo Burmeister M.',5);
INSERT INTO Review VALUES('243f8580-1164-43fe-ae7e-b226fd2454c3','5877d999-db2c-4fa1-8c7b-1bdc9997d6ff','Delicious pizzas!! Easy to digest as well. Service could be improved.','Lara Estrella',5);
INSERT INTO Review VALUES('f9741f20-5077-4579-a24f-d1aeb546f059','f0093689-5f36-4826-9c3c-a0043992715d','Me encanta el ambiente muy acogedor. Muy deliciosa la comida. El personal muy amable y Las mozas lo mejor♥️','jazmín moreau',5);
INSERT INTO Review VALUES('5d449922-8925-46ac-b438-656265c63e70','f0093689-5f36-4826-9c3c-a0043992715d','Lugar y ambiente maravilloso!, personal increible!, comida deliciosa!','Brem Molina',5);
INSERT INTO Review VALUES('6f895a59-6ff4-43e8-a631-dbf1514988b8','f0093689-5f36-4826-9c3c-a0043992715d','Je suis venue trois fois manger à Lili''s lors de mon séjour à Pisac. J''ai beaucoup aimé l''ambiance, le décor et les plats proposés. La sauce cacahuète des rouleaux de printemps est à tomber par terre et les gnocchis sont délicieux ! Le riz des sushis pourrait être assaisonné pour plus de goût. Enfin, la serveuse est vraiment adorable.','Lucie',5);
INSERT INTO Review VALUES('e2b84fd9-93d1-42ad-8caf-35b16b03878e','346e47df-34f3-4c4f-b764-04b5f75617f6','I thought the vegan nachos were fantastic, large portioned, and the person working was very friendly','Sita Ram',5);
INSERT INTO Review VALUES('430cb845-f247-481d-bbe1-db52ebd72650','346e47df-34f3-4c4f-b764-04b5f75617f6','Incredible food !! Great friendly service. Good value for money','Cara Shields',5);
INSERT INTO Review VALUES('af4a3a7c-141b-4f11-add5-50310aac71a1','346e47df-34f3-4c4f-b764-04b5f75617f6','Muy lindo el lugar y la comida rica','Katia Gonzales',5);
INSERT INTO Review VALUES('a31bf96a-d8ca-4a2c-bed5-4f49ef2860a4','416c0930-a6ea-4b1e-8128-4c21a7850c47',replace('El restaurant esta cerrado.\nThe restaurant closed.','\n',char(10)),'Kevin Assange',1);
INSERT INTO Review VALUES('6e64345f-93e4-4f16-abd3-e9eafc496bc1','416c0930-a6ea-4b1e-8128-4c21a7850c47','the sweetest restaurant with great food for a cheap price (25 soles for set menu!!!) the pumpkin soup was amazing and the service was fantastic','Millie Hodge',5);
INSERT INTO Review VALUES('9c28b4e2-6e3e-43dc-9da7-0238ea558830','416c0930-a6ea-4b1e-8128-4c21a7850c47','Very friendly family. I had the ceviche and it was delicious . They had the World Cup on. Great place to go alone or in group','A B',5);
INSERT INTO Review VALUES('a2311d5d-2c0a-405e-a119-c142581e4611','449d9b1a-f243-4b65-aa7a-b12d23884aa4','I love this hotel. Super cute rooms, comfy beds and bedding, heaters in room, hairdryers in bathroom.. & stylie. I am extending my stay. Amazing breakfast and really good Coffee . Looking forward to trying more things on the menu Beautiful garden, fireplace in the restaurant. And there’s a spa close by with traditional Inca flower baths, sauna and massage. It’s called unucha spa.. I am excited to go later today. Laundry service, hot showers, beautiful staff. Such a great place to rejuvenate after many days of hiking to see temples and exploring peru.','Isha',5);
INSERT INTO Review VALUES('b157fd6c-c620-4cc0-b967-3150f1b10b7f','449d9b1a-f243-4b65-aa7a-b12d23884aa4','I loved my stay here! It was cozy, clean, and had a beautiful atmosphere surrounded by plants and beautiful decorations. The location is amazing right on the main square. I loved being able to sit on the second floor balcony overlooking the square. The food and tea were incredible! The complimentary breakfast was great. The staff is all so kind and helpful. They quickly arranged taxis for me whenever I needed and answered any questions. I also highly recommend making time to go to the spa. I did the package with the massage, sauna, and herbal bath. It’s a beautiful terrace space with gorgeous plants growing that was completely private, it was such a unique and incredibly relaxing experience and Maria is so kind!','Mattie Sloan',5);
INSERT INTO Review VALUES('b130c779-fa85-46c0-8b3b-ad189b101149','4a548c27-39bd-4e40-8b78-66da4f266abd',replace('El tiradito de trucha y el risotto están muy ricos !\nSe siente la calidad en los ingredientes','\n',char(10)),'Gracias O',5);
INSERT INTO Review VALUES('b570beae-88e4-486f-98ff-cf7668301395','4a548c27-39bd-4e40-8b78-66da4f266abd','Says open until 8 but went at 730 and wouldn’t serve. Just change your opening hours to until 7 so people don’t go and expect to be served.','Daniel Okon',3);
INSERT INTO Review VALUES('774ecd8b-207e-4d5b-a876-b8feafd3df1d','4a548c27-39bd-4e40-8b78-66da4f266abd','Great quality food for reasonable price. Nice view and humble staff','Behzad ST',5);
INSERT INTO Review VALUES('725f24ee-ec35-4510-abbd-7d0cf2a227fd','c1a384da-4e2d-42a2-bab6-e82f071a3295','Yulvia is the best! The food is amazing- pasta trufada is incredible. Best food in pisac- wonderful location in the town square and such kind people. We have gone back so many times during our visit','Butler Mappus',5);
INSERT INTO Review VALUES('dc703d7f-bdd4-4c5a-b3b5-819e117d474c','c1a384da-4e2d-42a2-bab6-e82f071a3295','I went back the next night because I loved it so much. Edible art in a cozy and inspiring atmosphere✨☀️✨ I wish I was in pisac another day 🥰','Isha Jen',5);
INSERT INTO Review VALUES('99bea3d8-f59a-4a8d-94d1-080e2b2adf8b','c1a384da-4e2d-42a2-bab6-e82f071a3295','Recomendado, el chaufa de panceta, otro nivel.😘','David Marquez Chavez',5);
INSERT INTO Review VALUES('1dde3430-b3d9-49aa-b64c-d74c58828237','6095dea7-314c-4f4e-a0f5-d12f84b11777','Ambiente familiar com comida boa, servida e muito saborosa, recomendo pra que tiver descendo a montanha finalizando a trilha!','Lucas Passos',5);
INSERT INTO Review VALUES('839d30ce-d431-497a-b1da-db59c72866f8','6095dea7-314c-4f4e-a0f5-d12f84b11777','This is hands down the best meal ive had in weeks.  Silvia, the kind, welcoming woman who helped me, suggested the trout when i asked for a suggstion, and yall she did me right.  The Andean trout fresh as can be, perfectly done, flavorful.  The puree each slice lays atop make a perfect bite combo, and with slices of grilled veg and pina, serioslz delicious.  The sauce alongside is light and packed w flavor at the same time.  The chicha morada added to the flavor fest.  Highlz recommend, and am personally comingback tomorrow for more dishes and friendliness.  Than you Silvia and chefs!  ✨','anna wolfson',5);
INSERT INTO Review VALUES('61c8c4e3-2525-4f2f-bc67-6c1d777be482','6095dea7-314c-4f4e-a0f5-d12f84b11777',replace('Cuisine péruvien délicieuse.\nLes plats étaient copieux.\nTrès belle accueil.\nJe recommande vivement.\nNous avons très bien mangé','\n',char(10)),'Sophie Quagliaro',5);
INSERT INTO Review VALUES('2596f252-9e57-4ca3-9059-7a45e5c74950','214559c6-e5a8-4f98-a42c-ae0b497f233e','Un hermoso lugar y la atención de primera y tienes muy cera el Restaurante La Clorinda','Carol Medina',5);
INSERT INTO Review VALUES('36534e75-afae-47b7-8d6e-bca5ceed8667','214559c6-e5a8-4f98-a42c-ae0b497f233e','Karina wasi is the Beverly Hills of Pisac. Few places compare to the grounds beauty and the amenities of the main house at Karina wasi. Highly highly recommended to stay.','Katarzyna Demkowicz',5);
INSERT INTO Review VALUES('8cf754e7-4390-4b3e-991d-b45361639b7e','214559c6-e5a8-4f98-a42c-ae0b497f233e','Bello lugar,me encantó!','Teresa Bautista',5);
INSERT INTO Review VALUES('2a70413b-a3e7-42fc-8afc-68b240b4dd45','78712ea8-d042-465e-92ef-5bd3e052bb33',replace('*דיס המלצה על השאנטי בפיסאק*\n\nלפני שבועיים הגענו במיוחד כדי לסגור מקום ליל הסדר וחוהמ.\nהייתה לנו אפשרות לסגור במלון ב-60 סול אבל העדפנו להיות באזור של בית חבד כדי שיהיה לנו פסח כשר ושמח.\nסגרנו על *חדר 207 עם מרפסת וחלונות  ב-80 סול*, וביקשתי אישור הזמנה בווצאפ כולל המחיר כדי שיהיה מסודר.\nשבוע שעבר הבנו שנשאר יותר זמן בפיסאק אז יצרתי קשר עם הפקיד כדי להאריך את השהות ביומיים, זה אושר וכשבדקתי מולו כמה ימים אחכ שכל התאריכים סגורים לנו הסתבר *שהמחיר לילה עלה ל-150 סול* בגלל פסח.\nכשניסתי להסביר לו שהגענו מוקדם וסגרנו על חדר ומחיר מסוים ולא הגיוני שפתאום הוא משנה אותו נתקלתי באטימות מוחלטת וחב״ד פיסאק המלכים עשו הכל כדי לעזור.\nהצלחנו לגשר על הפער ושוב סגרנו ב-80 סול ללילה.\nבגלל שלא היינו רגועים עשינו הזמנה נוספת למלון שאז עלה 60 והתייקר ל-90 אבל הבנו ששמה ככל הנראה לא נתקל בחוסר הוגנות כזה ועדיף שלא נתקע אם יהיו בעיות.\n\nכשהגענו היום לשאנטי אמנם לא היו בעיות במחיר אבל החדר הנחמד שסגרנו מולו ונכתב בהזמנה התחלף בחדר *בלי שום חלון או אוורור* בטענה שאת החדר שהובטח לנו לא נוכל לשלם במחיר שאז סגרנו כי שוב ״עלו המחירים בגלל פסח״.\n\nאז אם אתם מגיעים לפיסאק תדעו שיש אופציות יותר טובות, הוגנות וזולות ואל תסמכו על ההזמנה שלכם בשאנטי אם עשיתם אחת כזאת מראש כי חבל על העוגמת נפש.','\n',char(10)),'אחינעם גהסי',1);
INSERT INTO Review VALUES('4b7e1f39-1d70-45dd-91b9-daed22facdfd','78712ea8-d042-465e-92ef-5bd3e052bb33','excelente Hotel🥰','SHIREL',5);
INSERT INTO Review VALUES('746ead0b-ad08-4451-a9e9-32fd589b1677','78712ea8-d042-465e-92ef-5bd3e052bb33','Excellent service, super clean rooms, very attentive staff, I recommend it and if you want a discount, ask for Amaru and he will attend to you and give you an additional discount.','AMARU INTI CCOYO OROSCO',5);
INSERT INTO Review VALUES('08d81da6-ee81-41b0-bbfc-88132baecbb0','9ffb2eb9-4795-42e8-8361-98a41ac686d7','Lugar muy agradable para salir de la rutina','sadam Ayma',5);
INSERT INTO Review VALUES('f7468359-d473-48f5-8810-867c414dae4b','9ffb2eb9-4795-42e8-8361-98a41ac686d7','Quiero agradecer a Pucara Lodge a Antony y su familia que nos atendieron super bien, pasamos un día espectacular, quisimos celebrar a solas con mi esposo su cumpleaños y nos fascinó, la habitación linda, paisajes asombrosos, una vista impresionante y la amabilidad con la que nos atendieron fue lo máximo, muchas bendiciones, de seguro que regresaremos.','BODAS PARA SIEMPRE WEDDING PLANNER',5);
INSERT INTO Review VALUES('1e0db63e-65b5-44d3-863c-7bdab2928279','9ffb2eb9-4795-42e8-8361-98a41ac686d7',replace('Such a wonderful experience we had there. The view, hourses, alpacas and lamas. Love the Lucas! 🩷🩷\nEverything creating such a magical atmosphere. Especially hosts! They’re an amazing people!\nHighly recommend!\nGet some soup for a dinner, you’ll not regret 😉','\n',char(10)),'Polina Soulmate',5);
INSERT INTO Review VALUES('f67e4ac4-514b-4f2e-a751-3619b6b7f42c','174850f9-6e46-4780-bee6-9f571c8c3d9c',replace('Rumi Lodge è un rifugio stupendo da usare come base per le visite alla Valle Sagrada.\nPulitissimo, con letti e materassi nuovi, acqua calda, stanze matrimoniali o con 3 letti, zona cucina e sala pranzo ampie. E specialmente la famiglia di Benito (il proprietario) è adorabile !!!\nAltamente consigliato','\n',char(10)),'Sento Experience',5);
INSERT INTO Review VALUES('14a3817b-1661-4f61-97be-0af1a7a9f324','174850f9-6e46-4780-bee6-9f571c8c3d9c',replace('⭐️⭐️⭐️⭐️⭐️ Truly Exceptional Stay.\nRumi Hotel is one of those rare places you don’t just stay — you feel. From the moment I arrived, the owners’ kindness left me genuinely speechless. Warm, sincere, and deeply caring — the kind of hospitality you simply cannot fake.\nThe space itself is beautifully authentic, full of soul and calm energy. You walk in and immediately exhale. Everything feels thoughtfully created rather than commercially staged.\nReliable hot water (always a blessing when traveling), and a lovely kitchen setup if you want to cook your own meals — practical details done right.\nWhat stayed with me most is the feeling of the place. Peaceful, grounded, heart-led. You can tell this hotel is run with love, not just business in mind.\nIf you value authenticity, warmth, and beautiful energy\nRumi Hotel is a gem.\nDeeply grateful for this stay. Highly recommended. ✨','\n',char(10)),'Jolanda',5);
INSERT INTO Review VALUES('007e4a6c-e16a-4c1f-9913-ef8bada209fd','174850f9-6e46-4780-bee6-9f571c8c3d9c','Fantastic Place, peaceful with great view. I loved the room, each detail with care and the kindness of Benito, the owner. I strongly recommend It!','Rosanna Liseno',5);
INSERT INTO Review VALUES('13c79663-b14e-4015-b067-6bd588c0d994','c3852103-560e-4b0f-bc18-ce6da5715c41','I had a great 6 night stay at the Ayra Hotel. The staff are amazing, very helpful and nice and made some fantastic breakfasts. The rooms were nice and modern, the location was great, and of course the great views of the Sacred Valley! Recommend to anyone staying in Pisac!','Samuel Wiegel',5);
INSERT INTO Review VALUES('8205c350-1c82-4b79-a3f5-fce6f4c10c5d','c3852103-560e-4b0f-bc18-ce6da5715c41','Muito aconchegante , limpo , as pessoas muito atenciosas e simpáticas . Atendimento vip .','Vera Tabernero',5);
INSERT INTO Review VALUES('09614ad9-23ab-49ad-91c9-981e92ff7a91','c3852103-560e-4b0f-bc18-ce6da5715c41',replace('Simplesmente maravilhosa!\nLocal tranquilo e muito acolhedor. Café da manhã muito agradável feito com muito carinho!\nRecomendo!','\n',char(10)),'Letícia Cruz',5);
INSERT INTO Review VALUES('337a364b-b475-4a82-bee1-81713e8e3e7d','fa1458a6-6bd1-4218-8e45-f318b24301d1',replace('We had a wonderful stay! The staff were incredibly friendly and helpful, making us feel welcome right away. The rooms were spotless, and the beds were very comfortable. We especially appreciated having a heater—it kept us warm and cozy throughout our stay.\nThe view of the surrounding Andes mountains is absolutely magnificent. It is in a nice quiet location with easy workability to the square and the market. Breakfast was delicious, healthy, and filling—a perfect start to each day. The artwork and décor throughout the hotel reflect classic Pisac style, tastefully done with a fun and vibrant atmosphere.\nWe truly enjoyed our time here and will definitely stay again!','\n',char(10)),'NK',5);
INSERT INTO Review VALUES('24021f24-7044-42e3-a1af-0836f934f20c','fa1458a6-6bd1-4218-8e45-f318b24301d1','Mega schöne Unterkunft. Sehr saubere Zimmer, wunderschöner Garten in der Mitte, toll zum Hinlegen. Jeden Morgen feines und frisches Fühstück. Wir würden wieder gerne herkommen ♥️ muchas gracias','Magdalena Müller',5);
INSERT INTO Review VALUES('a26e8c5f-615c-48b6-a599-95c15ecfeda9','fa1458a6-6bd1-4218-8e45-f318b24301d1',replace('We had a wonderful time at the Inka Guesthouse in Pisac. The rooms are simple but very clean and comfortable. The staff are extremely kind and friendly, always ready to help with great tips about the area.\n\nThe breakfast was absolutely delicious – one of the best we’ve had in Peru! The location of the guesthouse is also excellent, close to everything yet peaceful.\n\nWe truly enjoyed our stay and would definitely come back again. We can 100% recommend the Inka Guesthouse to anyone visiting Pisac!!','\n',char(10)),'Dirk',5);
INSERT INTO Review VALUES('30f8aeab-1e3e-41ba-b655-0f6b2fe1b237','e2e883bd-534f-49e2-a96b-31186fa97955','A really great experience. Over the top helpful. A 3 minute walk to the plaza. Every staff member is incredibly nice and helpful. I would definitely recommend staying there. I would go back for sure','J. Wysynski',5);
INSERT INTO Review VALUES('75d81104-3dfe-4cf9-a142-b5b978e8ab5a','e2e883bd-534f-49e2-a96b-31186fa97955',replace('Tuve una experiencia muy agradable en este hotel. Daniel y Yanet te reciben como si estuvieras en su case! Es un lugar ideal para familias, ya que ofrece un ambiente tranquilo y acogedor donde todos pueden sentirse cómodos. Las instalaciones están muy bien cuidadas y la limpieza es impecable en todas las áreas, desde las habitaciones hasta los espacios comunes. Los cuartos son cómodos y acogedores.\n\nOtro punto a destacar es su excelente ubicación céntrica, que permite acceder fácilmente a diferentes atracciones culturales y disfrutar de la gastronomía local a unos pasos del hotel. De hecho, Daniel y Yanet fueron instrumentales en indicarnos lugares mas lejanos donde pudimos experimentar y enamorarnos de Peru!\n\nYa estoy planeando mi próxima visita!','\n',char(10)),'nilda figueroa',5);
INSERT INTO Review VALUES('1a1b06b1-4d7b-4bc4-9c2c-74afeeaabcc9','e2e883bd-534f-49e2-a96b-31186fa97955','We had an absolutely wonderful week long stay at The Tranquility Hotel in Pisac! The rooms were clean and provided such a peaceful atmosphere to relax in after a day of sightseeing in the area. Each morning, the complimentary breakfast was a highlight—fresh, delicious, and the perfect fuel for exploring the Sacred Valley. El Tejano Mexican restaurant, which is part of the hotel had many excellent choices for both Mexican food and pizza. What truly sets this hotel apart is the people. The hosts, Daniel and Yanet, are incredibly gracious and welcoming, making you feel like family from the moment you arrive. That same warmth extends to the entire staff, who were all professional, kind, and attentive to every detail. Daniel was also able to arrange transportation, reservations, and guides to the local attractions making being a tourist much easier. If you''re looking for a comfortable and heart-centered place to stay in Pisac, this is it!','Mike Thompson',5);
INSERT INTO Review VALUES('9ae524c7-07ae-431a-901d-99063990e6e6','303dcd98-4738-4022-9c3b-a842b3eed691','Gracias por la experiencia. Fue realmente agradable disfrutar de todos los servicios y de la excelente atención brindada. Todo el lugar transmite calidez y tranquilidad, con espacios muy bien cuidados y un hermoso jardín botánico que complementa perfectamente la estadía. ¡Una experiencia que vale la pena repetir! 🌿✨','Royer Arnol Paucar Adrian',5);
INSERT INTO Review VALUES('7f8f232a-0216-4c19-a097-6a5a66f2e7c5','303dcd98-4738-4022-9c3b-a842b3eed691','Fantastic little hotel in the centre of Pisac. We stayed in one of the old rooms with a fireplace which really added to the atmosphere. Good breakfast and friendly staff/owners who don''t speak much English but go out of their way to make you feel welcome. I hope to visit again.','Dave Edwards',5);
INSERT INTO Review VALUES('65f325f9-b9ff-4594-8bc7-bc26afeceaae','b65eacad-6aa7-445e-83c8-92e871876f1f','The staff is extremely caring. Hot water during limited hours. I am not a vegan, but the included breakfast was still good. The location is delightful with great views from the fourth floor.','Nick Thompson',5);
INSERT INTO Review VALUES('b28f2ff7-6c66-42ca-b9e0-8c9a143ec87b','b65eacad-6aa7-445e-83c8-92e871876f1f','Fue nuestro hogar y base  durante 15 dias, nos sentimos en casa 🏡','lorena difilippo',5);
INSERT INTO Review VALUES('d7e302f3-6f58-40a3-bd3f-f82253df46fe','339e2e31-06c7-41db-be28-943bb11992f3','Виктория- Волшебный специались по работе с телом! Прекрасный человек и жизнерадостный Гид! Мастер Жизни и Профи своего дела!) Рекомендую встречу с ней🎉❤️','Владимир Кондырев',5);
INSERT INTO Review VALUES('428fddf3-e782-4577-889b-167c78c0cce7','339e2e31-06c7-41db-be28-943bb11992f3',replace('Огромное спасибо Виктории за этот невероятный опыт! Видно, что человек по-настоящему горит своим делом. Виктория идеально владеет языками, и это делает прогулку максимально комфортной.\nЧто особенно ценно — программа не была "шаблонной". Всё было продумано до мелочей: идеальный баланс информации, без перегруза, но и без упущенных деталей. Мы чувствовали, что маршрут подобран именно под нас. Искренне и очень-очень советую!','\n',char(10)),'Alex Myaskoveckiy',5);
INSERT INTO Review VALUES('659a18f8-d055-48f8-a943-6dd8feb44a85','339e2e31-06c7-41db-be28-943bb11992f3','Нашей группе очень повезло, так как нашим гидом была Виктория! Было все продумано до мелочей! Комфортное проживание, вкусная еда, классные магазинчики и маршрут по уникальным местам. Успели по максимуму насладится красотами сказочной страны Перу. Эта поездка останется на всегда в моем сердце ♥️. Путешествуйте с Викой, даже не раздумывайте, сэкономите нервы и время, проверено 😁.','Оксана Вострецова',5);
INSERT INTO Review VALUES('4ef12873-1e48-4796-9ca8-47c9d5109194','dea6685b-a7c3-4337-ad4b-d2c1e38091d8','Johana, de la agencia GV, nos organizó una intensa y maravillosa semana de tours por la zona sur de Perú. Todos los detalles estaban cuidados, y nos ayudaron en lo que pudieron a gestionar problemas con nuestros vuelos aún siendo un tema ajeno a ellos. Cuentan con conductores muy profesionales, vehículos modernos y limpios, y guías experimentados. Consiguieron que esa parte de nuestro viaje fuera muy satisfactoria.','Kara Trace',5);
INSERT INTO Review VALUES('ec7fba1c-d972-416f-b1cb-3b5318b1c600','0f0b6747-1d15-4807-866c-8bc3e3c22e94','5 soles','John',5);
INSERT INTO Review VALUES('0c9e922f-9fce-4cef-81f1-1242a9a68c0a','0f0b6747-1d15-4807-866c-8bc3e3c22e94','Cusco 5 soles','erick',5);
INSERT INTO Review VALUES('d44c4b65-8525-4d03-8ee9-94ed7fea8857','0f0b6747-1d15-4807-866c-8bc3e3c22e94',replace('2025年10月訪問\n\nピサック→クスコのコレクティーボ乗り場です。\n\nクスコまでは5ソルでした。','\n',char(10)),'pinya',4);
INSERT INTO Review VALUES('dec24205-56e5-44a8-8900-9ad3f3b0fcc8','b42540ba-8836-4b41-be41-75740fd73a8e','Choquequirao Trek es una experiencia única con maravillosos paisajes un Trek 100% recomendado, al inicio la caminata es un poco difícil pero la experiencia y la vista lo vale todo. 🏕️⛰️❤️❤️','Monica Aslla',5);
INSERT INTO Review VALUES('5b7469a8-7fa1-40b1-bcc2-9c89e78739f2','f7505ff9-4607-4c63-b733-ac3ca8640a44','Good pizzas. Very good service & drinks!','Vaishakhi Pilankar',5);
INSERT INTO Review VALUES('f89d600d-782e-4b1d-adf6-0bc3f2d7f5a3','f7505ff9-4607-4c63-b733-ac3ca8640a44','ロモサルタードのピザがとても美味しかったです！ピザ焼く体験も無料でさせてくれて嬉しかったです。','Aoi',5);
INSERT INTO Review VALUES('b4da7170-ec35-429f-935c-330c374c7c4e','371b9610-21a5-4968-8b32-eac5ed2db902','Good food with some traditional dishes','Sebastian Gonzalez',5);
INSERT INTO Review VALUES('9ed11f6a-f9c7-4f1f-a961-ce6f7ef904b6','371b9610-21a5-4968-8b32-eac5ed2db902','Excelente','Carla Delgado',5);
INSERT INTO Review VALUES('b66f9d28-66ac-486c-a5c9-a6f54e5646e0','371b9610-21a5-4968-8b32-eac5ed2db902','The food was delicious, the menu was very affordable. I got to eat next to the river. What else can you ask for. Oh yea, the staff was very charming and generous. Highly recommend','etienne ouellet',5);
INSERT INTO Review VALUES('cd509d18-0af9-4bbb-acd3-a612c8e3af20','35ec336b-72b3-4ce1-9808-1eb0bdfc57cc',replace('On trouve d''excellentes adresses au Pérou, mais j''ai particulièrement envie de m''arrêter sur ce restaurant. Déjà, quel plaisir de se poser au dessus de la place du village et de se laisser emporter par l''instant... Ensuite arrive la surprise, des lasagnes végétariennes juste exceptionnelle.. la déco, le contenu... Tout est parfait. Quitter ce lieu avec l''envie d''y revenir le soir même. Le filet de truite exquis lui aussi.\nEt l''accueil, il est emplis  de bienveillance, souriant et attentionné..\nUn grand merci','\n',char(10)),'Olivier FAYET',5);
INSERT INTO Review VALUES('69e7088e-92a8-4300-bee8-c825b8bc6906','35ec336b-72b3-4ce1-9808-1eb0bdfc57cc','Koricancha was our favorite spot in town. We were met with smiles and friendliness everytime we went! The guacamole was so good and the fries were exactly what we needed (ketchup and all!). Couldn''t recommend this spot enough 😁','pdobbie',5);
INSERT INTO Review VALUES('ef7739b5-9014-4d5e-a173-ef574d97cec1','35ec336b-72b3-4ce1-9808-1eb0bdfc57cc',replace('Buena comida, precios razonables.\nLa zanahoria vino algo dura o cruda, pero el resto bien.','\n',char(10)),'Sergio Martín Encina',5);
INSERT INTO Review VALUES('b1b4c2e3-cab3-45f4-9ee0-344f94d515c0','f8cc3694-5363-439e-a989-fb380f32c908','The food was excellent and the host (Gonzalo) was very friendly too. We were traveling with a toddler and they were very accommodating to our requests. We tried the Lomo Saltado and the grilled trout and with were excellent.','Prithvi Somasundaram',5);
INSERT INTO Review VALUES('2714cae4-c02c-43cc-9d45-3ca9ddfe9ec3','f8cc3694-5363-439e-a989-fb380f32c908','Un restaurant élevant les spécialités andines a un niveau gastronomique, l’expérience était parfaite de l’entrée au dessert. Notre serveur était particulièrement attentionné et sympathique, expliquait tout, était de bons conseils.','Hadrien Grenacs',5);
INSERT INTO Review VALUES('befd13e0-0796-4730-9a4d-b7559c276e1f','f8cc3694-5363-439e-a989-fb380f32c908','I’d highly recommend this place. We decided to visit because of its perfect 5-star rating, and it absolutely exceeded the expectations! Don’t look further, just go here when visiting Ollantaytambo.','Lotte Jeuken',5);
INSERT INTO Review VALUES('aa904741-0f14-47d4-a28c-2a617893dcc7','97511345-7919-4c3c-9b42-a5737fc8c637','We had such a wonderful experience at this restaurant that I''m already planning tomorrow night''s dinner there and know exactly what I will order.  Tonight, we had the sopa de quinua (quinoa soup), maiz con queso (corn with sauteed mushrooms and cheese), guacamole with tequenos stuffed with Andean cheese as dipping sticks, and grilled alpaca skewers.  Each dish was perfectly prepared, mouth-watering, and unique.  This is a family-run business with the sweetest and most earnest couple and their 2 children.  My husband even asked them for extra business cards for our hotel to recommend to other guests - I''ve never seen him do this in 15 years of marriage!  Leaving the restaurant, I actually felt sorry for the tourists walking past without entering for a meal.  For reference, we ate at Merito in Lima last night and, although a miraculous gastronomic experience, I did not feel compelled to write them a review the way I do tonight.','H Chang',5);
INSERT INTO Review VALUES('fbbecea3-0bfa-4d60-984f-1d4627c63fcd','97511345-7919-4c3c-9b42-a5737fc8c637','Came here for an early dinner after a long ride from Cusco, greeted with a warm smile and chose to sit upstairs to enjoy people watching with our meal. Shared quinoa soup, guacamole, queso corn and mushrooms, and anticuchos. Flavors were amazing and felt like a delicious and healthy home cooked meal! Lots of interesting menu options and can’t wait to go back to try them!','William Staerker',5);
INSERT INTO Review VALUES('969653a7-4de6-4187-a98d-72de420c959a','97511345-7919-4c3c-9b42-a5737fc8c637','Excelente comida! Fresca, sabrosa y buen precio. Pidan la hamburguesa de alpaca. Exquisita! Y el postre de pie de manzana con helado!','Alexander Alfaro Rivera',5);
INSERT INTO Review VALUES('1408c3b3-f4e3-4cac-89b7-1b6e7750d727','dda247a4-d8d2-4bee-9743-47b6d7f92fdf','Delicioso "lomo a la piedra", melhor lomo que comemos no Peru, no entanto o atendimento deixou muito a desejar. Coca cola de 600ml servida quente e sem copo a própria atendente me perguntou se eu queria um drink 2x1 no happy hour, ao ser questionado sobre o tamanho dos copos ela me disse que os 2 copos eram do tamanho do copo de drink usual. Ou seja, nao existe happy hour. Infelizmente a experiência nao foi positiva, apesar da deliciosa comida.','Igor Fleury',3);
INSERT INTO Review VALUES('b0e6a669-0cec-43fe-80a5-56ac4c2b82ef','dda247a4-d8d2-4bee-9743-47b6d7f92fdf','Better than many of the great restaurants in Cusco. Had the Trilogia Inka a la piedra. Nice view from the balcony. Highly recommend','Eknoor Singh',5);
INSERT INTO Review VALUES('fed1a74c-19f7-474e-a62f-587d92f99195','dda247a4-d8d2-4bee-9743-47b6d7f92fdf','Muy buena atención y la comida exquisita! El lugar muy lindo y con una vista hermosa al pueblo','cintia londero',5);
INSERT INTO Review VALUES('8d0977ec-8fdd-4e77-8c8e-2352f5bf78fd','d01c1841-5d04-4dc3-a206-42a270dcf5d3','Food is good. View is amazing! It was quite pricey for what I got though','Tarek El-Gaaly',4);
INSERT INTO Review VALUES('6b8b5846-9d3e-44d1-8493-ccfa3bcfde7e','d01c1841-5d04-4dc3-a206-42a270dcf5d3',replace('Lo único malo fue el principio, después de ofrecer un menú de 40 soles con bebida, la bebida dejó de estar incluida. Pero rectificaron y añadieron una limonada y un pan de ajo.\nY los dos platos estaban muy ricos, tanto las dos sopas, como la trucha o el lomo saltado. Y en todos ellos, acompañamientos muy generosos.\nBuenas vistas y servicio correcto','\n',char(10)),'Joan Font',5);
INSERT INTO Review VALUES('5b11db46-1dba-419c-a4f6-e7141d2f343d','d01c1841-5d04-4dc3-a206-42a270dcf5d3','Excellent restaurant and service. I dined here twice because it’s one of the best around the area','Amy Chia-li Yu',5);
INSERT INTO Review VALUES('79df780e-bb43-4d47-9803-63f557a15faa','463c9e42-89c9-453e-b5e9-4f419cc7b8ae','Highly recommend. Local typical food with great quality for the price. Unique atmosphere and owners.','Virgen Roy',5);
INSERT INTO Review VALUES('eeadf02a-d837-4ee8-8944-4c8dc2d0c5a9','463c9e42-89c9-453e-b5e9-4f419cc7b8ae',replace('We got into town super late after a really long flight and found this place was still open and had vegan options.\n\nI am very glad we went here over anywhere else, since my boyfriend suddenly got altitude sickness and every one of them jumped in to help. I was amazed at how they immediately they tried to help my boyfriend feel better with bottled water, fresh air, and a comfy seat. (All of this was closer to closing time too where they could have just gone home if they wanted). It’s rare to see this selflessness nowadays, so I’m so thankful we stopped by!\n\nAll in all, before he got sick I had really tasty quinoa soup and my boyfriend who’s vegan got the fried potato dish on the vegetarian section with pickled veggies and rice. That also tasted great!','\n',char(10)),'Stephanie Marker',5);
INSERT INTO Review VALUES('a6574ac7-3078-4f8e-bdf7-41075a3d258e','463c9e42-89c9-453e-b5e9-4f419cc7b8ae','Delicioso almuerzo, mi esposo y yo disfrutamos con una deliciosa sopa de quinoa servida en un lindo plato de piedra y de fondo trucha a la piedra acompañada de papas , ensalada y deliciosas salsas, tmb anticucho de alpaca.','Luzmaria luzon riveros',5);
INSERT INTO Review VALUES('fc6ede7b-3db9-451e-a032-6e4b500eaf4d','65565424-4999-49fc-8eb8-013875659180','Gluten free options - super yummy came back three times! Great view too!','Shannon Toogood',5);
INSERT INTO Review VALUES('900fbce7-792a-4a34-8664-129b40527aa7','65565424-4999-49fc-8eb8-013875659180','Had an iced latte and the “full bowl” after a long day of hiking. They were so good and the owners were really kind. And we got chocolate chip cookies to go :) They have a huge variety on the menu and it was a perfect spot to hang for a bit!','Sophie Golden',5);
INSERT INTO Review VALUES('888a3d48-c753-4f50-8b3c-53734734b50f','65565424-4999-49fc-8eb8-013875659180',replace('Ambiance is nice and friendly servers.\n\nBut slow service and food is just ok, nothing exceptional given the high prices.\n\nHad the cheese empanadas and brownie. Both were below average as compared to other food venues in town','\n',char(10)),'Faisal Naeem',3);
INSERT INTO Review VALUES('edcf2588-aa7a-45de-8101-bfbbf35ab558','439d7729-b043-428c-a228-b14bc24a754c','Very good peruvian specialties.','Nicolas Fischer (nicofisch5)',5);
INSERT INTO Review VALUES('0aecb70c-dfc0-4a13-b805-1958015aae77','439d7729-b043-428c-a228-b14bc24a754c',replace('Ausgezeichnetes Restaurant mit guter Lage. Aufgrund der Vielzahl von guten Bewertungen sind wir auf das Restaurant aufmerksam geworden - und was soll ich sagen, hat sich sehr gelohnt.\nSehr leckere Speisen, wir kommen wieder.\nPreis / Leistung war für die gute Lage hervorragend.','\n',char(10)),'Philip K.',5);
INSERT INTO Review VALUES('f2d56299-9364-4966-ba9e-f6f0f584fcb2','439d7729-b043-428c-a228-b14bc24a754c','Delicious & beautifully presented juices, amazing corn soup & great service!','Lexi Tichenor',5);
INSERT INTO Review VALUES('400af183-20af-4645-af6a-5a8ef4919925','5ebe03a1-b917-4249-aeb0-2c9835a9c9c2','Not to be missed, excellent food, perfectly served, surprising and 5 star Peruvian dishes. Glad we ordered a cocktail which was expertly prepared tableside. Hands down our best meal in the Valle Sagrada.','Pawel Janowski',5);
INSERT INTO Review VALUES('910199d7-80b7-4b08-be9a-f1318f580b1e','5ebe03a1-b917-4249-aeb0-2c9835a9c9c2','Our group of 8 had lunch at Amanto Sagrada today after a morning tour of the fabulous Ollantaytambo Inca Temple of the Sun and astronomical site. Bianca took great care of our group. The art work, flowers, and sculpture over the serving area were lovely. A great selection of music provided a good background. The meal was superb! It was beautifully and artistically presented -- and the flavors incredible. Congratulations to Amanto for exceeding our expectations and creating a wonderfully memorable meal in Ollantaytambo. Thank you so very much!','Nancy Brian',5);
INSERT INTO Review VALUES('49ef2f96-e67c-4f13-9b35-a2bba901894f','5ebe03a1-b917-4249-aeb0-2c9835a9c9c2',replace('Exquisito y muy bonito el ambiente.\nNos atendió Eva y su trato fue muy amable y atento.','\n',char(10)),'Aaron Gorojod',5);
INSERT INTO Review VALUES('05f4833a-07c7-44d5-81c0-d4f9c11559fd','5729c905-b7de-44ab-b951-3af9e002014f','Get the grilled alpaca. Made me a fan …. Almost over beef 😰. So good we went back the following night and both order the grilled alpaca.','Brandon Rodriguez',5);
INSERT INTO Review VALUES('48ff0606-19ff-47d8-b2ca-e1ed176c92b1','5729c905-b7de-44ab-b951-3af9e002014f','Great spot in ollantytambo. I had the stuffed trout and it was amazing. Not bony at all. The presentation was beautiful. The chefs take pride in the food and the staff is wonderful. And the prices are very reasonable.','C L',5);
INSERT INTO Review VALUES('b539123c-35d4-4485-8b61-e4234d13033b','5729c905-b7de-44ab-b951-3af9e002014f','MELHOR carpaccio que já comi na vida! Atendimento impecável, lugar charmoso com uma vista linda! Pagamos 35 soles pelo menu turista, recomendo MIL POR CENTO! Vá e não irão se arrepender','Amanda Albertoni',5);
INSERT INTO Review VALUES('c72a540e-3280-4aa5-bf01-4f7169e393cf','38bf0b33-38e3-4592-9751-a7a741c121d7','Estuvimos de visita aquí la semana pasada y la comida estuvo increíble, pero la camarera tenía una mala actitud. Nos lanzaba miradas de desagrado —como si no nos diéramos cuenta— y no empezó a ser amable hasta que llegó el momento de dejarnos su tarjeta y pedirnos una reseña 😂. Pero, dejando a un lado a ella, literalmente todo lo que comimos estuvo fantástico. Definitivamente lo recomiendo. Quizás ella estaba teniendo un mal día. Fue la mejor chicha morada que probamos en la zona, y todo era muy fresco. ¡Los pimientos rellenos son algo que tienen que probar sí o sí!','James Gonz',4);
INSERT INTO Review VALUES('714cbee7-31d6-4a8e-91b0-c1b866794997','38bf0b33-38e3-4592-9751-a7a741c121d7',replace('Impecable calidad y atención...Cada plato perfectamente diseñado. Cada sabor y color en su perfecta combinación. Pedimos un menú de 4 pasos con comida peruana. Exquisito sabor\nLa atención también muy reconocible... Amabilidad en cada atención.\n\nMuchas gracias al mozo Carlos que nos atendió','\n',char(10)),'Mariela Martinez Herrero',5);
INSERT INTO Review VALUES('1222f546-db0c-4d55-840b-9f8526d107e9','38bf0b33-38e3-4592-9751-a7a741c121d7','Excellent!!! Delicious local food presented beautifully with care to every detail. A Peruvian delight. Highly recommend. I look forward to when I can return.','Janine S',5);
INSERT INTO Review VALUES('3ac5b7c8-ffb4-4241-90b2-0272ec3f5fe2','2cd7107a-7a58-4f25-88c3-a2bbfe62c6df','Notre serveur a été très respectueux envers nous d''une grande politesse et amabilité. Les plats sont bien cuisinés et très bien présentés','Marc',5);
INSERT INTO Review VALUES('39b238f5-108d-464f-ae37-5c5f3d918e95','2cd7107a-7a58-4f25-88c3-a2bbfe62c6df','A very average pasta with mushroom dish -too smothered in pesto sauce','pete',3);
INSERT INTO Review VALUES('61945bc7-0ed4-43e4-8bc0-d21ab405ec37','2cd7107a-7a58-4f25-88c3-a2bbfe62c6df',replace('We had an amazing experience: the menu turistico is excellent (40 soles with entrada, plato principal y postre). The dishes were fresh, tasty and delicious. The vegetables and fruits come directly from the owners’ field. The owners are super kind and the atmosphere is relaxed and cozy. I can’t wait to come back here again!\nPs. Try their digestivo a la muña 😋','\n',char(10)),'francesca sacchi',5);
INSERT INTO Review VALUES('6191c582-9ef4-48f2-b8f0-61d4479f7ecd','29c29b18-0095-4656-8be0-1953a67ac3e3','Itt kifejezetten finom volt a vacsora. Tökleves kiváló. Megkostoltam a tengerimalac sültet is. Kicsi drága de finom','Viki Ivanicsne',5);
INSERT INTO Review VALUES('f281d736-8ee4-4924-900e-f63bb56cbf85','29c29b18-0095-4656-8be0-1953a67ac3e3','Excelente 👌','Michael Cano',5);
INSERT INTO Review VALUES('0fb015fa-6322-4a10-aa4a-a144879b39b0','29c29b18-0095-4656-8be0-1953a67ac3e3',replace('The food here is straight-up Michelin level. Every plate looks like a piece of art—the colors and presentation are so stunning that I actually snuck a peek at the kitchen just to see how they do it. To my surprise, the kitchen looks like any regular setup, which just proves that it’s all about the chef’s incredible skill and heart, not fancy equipment.\n\nWe came with a group of 31, and even the die-hard meat-eaters among us were blown away. One of my friends even said, "If vegetarian food always tasted like this, I’d give up meat for good."\n\nThe flavors are just as vibrant as the colors. Every bite was a 10/10. It’s rare to find a place where the food is this beautiful AND this delicious. An absolute highlight of our trip!','\n',char(10)),'Pazu P',5);
INSERT INTO Review VALUES('45e2be00-e1b4-43a1-9f83-cb02c3589481','6e24aaf1-eea3-4fe2-9f3f-dc4c8dba8b0c','Unassuming looking, but very tasty food for a surprisingly cheap price. And they didn''t ask for a review, so the 5 stars is actually legitimate (unlike many places that push for reviews)','Thomas Stur',5);
INSERT INTO Review VALUES('6a5be5e5-f7b9-4f96-9387-1335b18c9805','6e24aaf1-eea3-4fe2-9f3f-dc4c8dba8b0c','This place is excellent!! Ate here three times during our three day stay in Ollantaytambo. The trout ceviche is fresh and delicious. The beef in the lomo saltado is tender and great. Super friendly, laid-back, authentic atmosphere. Got a free little keychain at the end :)','Roberta Lee',5);
INSERT INTO Review VALUES('883d7891-c7be-4092-840d-51e01145e4c2','6e24aaf1-eea3-4fe2-9f3f-dc4c8dba8b0c','Amazing food, great atmosphere, amazing service. Best Lomo Saltado i have had yet in peru. Carlos you are doing amazing!','Zoe Cox',5);
INSERT INTO Review VALUES('e3028720-36c8-4868-8958-4d1862d9f64a','4a2f854d-816a-4152-b098-a02687acfd00','Lovely food!','Cara Shields',5);
INSERT INTO Review VALUES('2401af79-5c40-4b8a-8d51-64d8bc516513','4a2f854d-816a-4152-b098-a02687acfd00','This place is off the square a small walk. We stayed for 3 days and this was one of the best meals we have had here. The chicken was so fresh and tasty.','Sean Pease',5);
INSERT INTO Review VALUES('e160d3d0-7db4-4539-ab91-ef4e94f03e74','4a2f854d-816a-4152-b098-a02687acfd00','Das Essen ist hervorragend. Lokal befindet sich in einer Marktgasse','Marika Thommen',5);
INSERT INTO Review VALUES('0d808d6c-6649-4f51-af99-44d3f7851f40','68f9bcfa-79fc-44ea-99e3-991bf7548693','We got sick in our trip (both my partner and I ended up at the hospital) and we tried to communicate with them, we communicated only few our later our free cancellation window through booking.com. There was no communication from the hotel, they didn’t tried to find a solution ( e.g changes of dates, voucher for later stay etc…)and just charged our credit card. This is very strict and shows a clear lack of compassion and professionalism. This is the only hotel in our trip in Peru which behaved like this. Disappointing, I would stay away.','Luca Naitana',1);
INSERT INTO Review VALUES('4d4e85f1-c77b-401d-a16f-1b0c221eae6f','68f9bcfa-79fc-44ea-99e3-991bf7548693','See the other reviews. Friendly people, and the place has a nice atmosphere. While having breakfast, the sounds of people having fun with eachother came from the kitchen. Pleasant vibes.','Kees de Jong',5);
INSERT INTO Review VALUES('74a38bac-019d-49b5-b655-d33ff13e1075','68f9bcfa-79fc-44ea-99e3-991bf7548693','Great service and people who are always willing to help. It’s warm, essential breakfasts, fascinating inside ❤️‍🔥','an Domchenko',5);
INSERT INTO Review VALUES('5de3cffe-43c9-4e70-9fc9-f8a66365afe3','333bb906-b9a6-4fd9-a68e-8224fb5515ed',replace('Estancia fantástica en Apu Lodge. Un lugar muy entrañable, con un equipo súper atento y siempre dispuesto a ayudar.\n\nA pesar de nuestros madrugones, el desayuno estaba siempre listo y cuidado al detalle. Además, nos facilitaron toda la organización (guía, recogidas, etc.), lo que hizo el viaje mucho más cómodo.\n\nMuy contentos. Lo recomendamos 100%.','\n',char(10)),'Marta Angulo',5);
INSERT INTO Review VALUES('b7306671-819a-4b78-b534-d3a8545446e4','e5dadc40-9f3c-4523-9cd4-4e106c550bf9','Spirituality is a lie.','Holi',1);
INSERT INTO Review VALUES('f0600dc1-0f0b-4490-a698-9504256c8999','e5dadc40-9f3c-4523-9cd4-4e106c550bf9',replace('Une expérience personnelle désagréable dû à un manque catastrophique de professionnalisme de la part des équipes. On nous a installé dans une chambre, tout allait bien, on donne nos passeports (ils savent qui nous sommes donc) pour qu’ils fassent le checkin et nous leur donnons un généreux pourboire pour leur gentillesse.\nPremière chose étonnante, on nous invite à nous reposer dans la chambre mais rien ne nous est présenté, ni les infrastructures, ni les règles relatives aux repas et aux heures de checkout, ni les modalités de déplacement vers la ville.\nNous passons à table au restaurant de l’hôtel et entre l’entrée et le plat principal un membre du personnel vient nous trouver pour nous indiquer qu’il s’était trompé et que nous devions changer de chambre. Soit, un peu déçus mais nous refaisons vite nos affaires, on nous change de chambre. La nouvelle chambre n’est pas propre, des détritus sont présents et des cheveux un peu partout. Le lendemain matin au petit déjeuner, on nous informe qu’ils se sont encore trompés et qui faut changer une nouvelle fois de chambre. Nous refaisons nos bagages pour la 2ème fois et nous voilà dans une chambre sans vue. Pour se faire pardonner, on nous propose une bière le soir (?). Le lendemain au moment du départ, les bières étaient bien notées et à payer sur la facture. Dernière phrase assassine de notre hôte : « vous voulez donner un pourboire ? ». Je suis resté interdit face à l’audace. Considérant le prix payé je trouve que la qualité du service n’est absolument pas au rendez vous. C’est dommage vu l’emplacement idyllique et la vue à couper le souffle. Je vais paraître aigri mais il est trop facile de se reposer sur le lieu pour proposer une expérience moyenne. La vue sur la vallée est splendide, même en dehors de Stardome Spiritual Experience','\n',char(10)),'Hadrien Grenacs',2);
INSERT INTO Review VALUES('a5d78439-df88-45f0-a9f6-331ba783f981','e5dadc40-9f3c-4523-9cd4-4e106c550bf9',replace('En Stardome vives una experiencia distinta, estas alejado de la ciudad, se encuentra en la parte superior de una montaña. Aquí puedes relajarte y escaparte del ruido de la ciudad.\n\nSepare la habitación Snake por una noche ($250), nos recogieron desde Ollantaytambo, fueron flexibles con el check in. (Ingresamos después de las 2:00 pm)\nAl llegar, vivimos la experiencia de Hot tub con cena romántica ($160), la comida de esta experiencia fue exquisita y las vistas del valle fueron muy bonitas. Luego subimos al domo a observar algunas estrellas (Tip: Las estrellas suelen verse mejor cuando no hay Luna Llena)\nAl día siguiente amaneció lloviendo (Tienes paraguas disponibles para usarlos), tomamos desayuno y salió el sol. Visitamos la granja y el templo del condor, donde nos encontramos con Inti (La alpaca de la granja) y nos pudimos tomar algunas fotos. Luego nos llevaron de regreso a Ollantaytambo (Previa coordinación con nosotros), el check out es las 11:00 am.\n\nLa experiencia para nosotros fue muy bonita.\n\nLo único en lo que podrían mejorar sería en dar mayor detalle en cuanto al uso de las instalaciones (Indicar todo lo que incluye la habitación, entrega de llaves al hacer check in, uso del wifi e indicar todo lo que se puede usar en el espacio de la experiencia Hot tub + cena romántica).\n\nPunto importante es que todas las personas que trabajan aquí son muy amables y serviciales. El chef es excelente, ha sido una de las mejores comidas que probé en Cusco.\nSin duda tienen que vivir la experiencia Stardome.','\n',char(10)),'Ronald Alejandro Martinez Sarazú',5);
INSERT INTO Review VALUES('4ac709ea-4472-4c1f-85c6-2fe8db39f2d4','0ee862b7-778c-4f62-9858-c95be3a9cd3e','La señora Ana y sus compañeros en el hotel Andenes del inca fueron my atentos y amables. Se coordinó muy bien con nuestras actividades, conductores, y guías para el tour que teníamos programado. Aún hasta nos proveyó de un desayuno. Muchas gracias señora Ana!','Efrain Bastida De Jesus',5);
INSERT INTO Review VALUES('96290154-07a5-4a4e-86ab-2fd7fccc0b05','0ee862b7-778c-4f62-9858-c95be3a9cd3e',replace('The room was a good size and comfortable overall. The staff were very friendly (thanks Alvaro) and welcoming, which made the stay pleasant.\n\nThe breakfast selection was rather limited, but for the price, the hotel was still good value. Overall, it’s a solid option for a one-night stay.','\n',char(10)),'Pi',5);
INSERT INTO Review VALUES('95529827-f876-4803-aca7-26439e964e03','0ee862b7-778c-4f62-9858-c95be3a9cd3e',replace('Experiência excelente! O ponto alto foi a hospitalidade: recebemos um upgrade de quarto cortesia que fez toda a diferença. Destaque especial para o **Álvaro**, que foi espetacular e cuidou de cada detalhe.\n**Prós:**\n* Quarto limpo, organizado e com Smart TV e Wi-Fi.\n* Cama aconchegante e banheiro impecável e limpo.\n* Café da manhã justo! Custo/benefício.\n* Atendimento nota 10 do início ao fim.\n**Melhorias:**\n* **Quarto 2:** Precisa de cortina blackout (a janela fica ao lado de uma lâmpada externa deixando o quarto claro durante à noite).\n* **Água quente:** A temperatura oscila e esfria quando o hotel está mais cheio.\n* **Travesseiros:** Poderiam oferecer opções com densidade intermediária.\nRecomendo muito e voltaria com certeza!','\n',char(10)),'Luis Oscar',5);
INSERT INTO Review VALUES('6a8f2fa8-0a65-405b-8e6c-e42ec0e30f54','1064a208-1365-4550-a292-e36acf4149a4',replace('We loved staying at this place!\nOn the day we arrived, I felt a bit ill due to the altitude. The team took care of me like family, bringing me tea and food and showing genuine concern. Alex and the team were incredibly friendly, explained everything to us, and were always ready to help with anything. We truly felt like we were staying with family.\n\nThe place and the garden are beautiful—peaceful and a bit hidden, yet still very close to the center of Ollantaytambo.\n\nI hope we can come back one day.\nSarah','\n',char(10)),'Sarah Miesler',5);
INSERT INTO Review VALUES('9b6461ae-e5cd-40e5-bbd7-61a30caa5733','1064a208-1365-4550-a292-e36acf4149a4',replace('We had such a great time at this hotel! It’s in a fantastic spot—only a short walk from the main square, but it’s tucked away enough that it stays really quiet and peaceful at night. The courtyard is absolutely beautiful and was easily our favorite place to hang out.\nThe staff were wonderful, but a huge shout-out to Alex. He was incredibly helpful with our daily plans and made sure we had absolutely everything we needed. As for the rooms, they’re huge and have so much charm, plus the bathrooms are modern with plenty of hot water (which we really appreciated). Breakfast was fresh and delicious every morning, and the whole neighborhood feels very safe and homey to walk around. Honestly, it felt like a little sanctuary','\n',char(10)),'Michael Silverman',5);
INSERT INTO Review VALUES('c931e947-605a-43ba-a493-3941b9855cac','1064a208-1365-4550-a292-e36acf4149a4',replace('I stayed with my two teen daughters for three nights in March. Alex and his staff were so accommodating and are genuinely friendly people. They helped organize transport from Cusco and back again. This was a huge weight off my mind.\nThe hotel is in a great location - it took us just 5 or 6 mins to walk into town and the archaeological ruins. Having the outdoor grassy area with amazing views was so nice to relax in between activities. The breakfast was delicious. The rooms are lovely- we also appreciated the smart tv/streaming channels as an option.\nStaying in Ollantaytambo was the best part of our trip - so much to do. Hotel Tierra Inka was the perfect place for our stay. I would recommend as a place to all my friends and family.','\n',char(10)),'Niamh Hillman',5);
INSERT INTO Review VALUES('557fc3a3-1da9-4e8e-b401-09af6d5e5721','ea8ad3fb-cff6-415e-a582-0fa3fe5f9426',replace('Chambre confortable, mais problème d’eau chaude régulier, et il n’y a plus d’eau à partir de 22h c’est apparement coupé dans le quartier.\nPetit déjeuner excellent : bol de fruits frais yaourt, pain, œufs brouillés…\nService de laverie catastrophique : linge mal voir pas lavé pour certains vêtements, tâche de lessive sur d’autres. Linge rendu humide et non pesé … elle l’a pesé après alors qu’il était encore mouillé. Oubli d’une partie du linge dans la buanderie… le service promet un linge sec et plié : faux nous l’avons retrouvé humide et dans une bassine le tout pour le prix (8soles) du double qu’une laverie en ville (4 soles)','\n',char(10)),'Camille Vig',3);
INSERT INTO Review VALUES('fdfa5b07-6658-4859-8059-f3ad287122ac','ea8ad3fb-cff6-415e-a582-0fa3fe5f9426','Séjour fabuleux, les chambres sont situées au bordd''une rivière. Dormir avec le bruit de l''eau est une expérience incroyable. Edith est une hôte extrêmement gentille, qui m''a attendu le soir lors de mon arrivée tardive. Le petit dej est bio avec de produits frais et faits maison. Je recommande les yeux fermés !','benjamin cafora',5);
INSERT INTO Review VALUES('e980fb1e-b2e1-42d5-9171-58e435771f1c','ea8ad3fb-cff6-415e-a582-0fa3fe5f9426','This is a great place to stay. Stan and Edith are amazing hosts, and also make great chocolates on the side. My only regret is we did not stay long enough to see the all the amazing sites. The room was clean and comfortable and the breakfast was delicious. Definitely check this place out if you are staying in Ollantaytambo.','Michael Hotchkiss',5);
INSERT INTO Review VALUES('79b3d668-300d-4cdc-b605-e373bbfd1ce4','a079c2fa-7503-4c97-80dd-c11337187217',replace('I stayed at Hotel Samanapaq in the Sacred Valley as part of a group of eight adults (ages 40–50) and unfortunately had a very poor experience.\n\nThe property is in significant disrepair and should not be marketed as a hotel in its current condition. The mattresses were extremely thin (with no box spring), resulting in back pain and a sleepless night for several of us. Portable heaters were provided but were not sufficient to properly warm the rooms.\n\nOne guest experienced a water leak in her room and discovered visible mold on the ceiling. She woke up with congestion and allergy-type symptoms the following day. During the same stay, the fuse blew in her room while using the hotel-provided hair dryer, leaving her without heat for the remainder of the night.\n\nIn my own room, the bathroom mirror was cracked, a nightstand lamp was broken, there was a broken tile under the bathroom sink, and the walls were visibly damaged. Overall, the property felt poorly maintained and, in at least one case, posed a potential health concern.\n\nWhen concerns were raised with the property owner, the response was unwelcoming. We were told that a room with better beds was available for an additional charge, which was disappointing given the overall condition of the hotel.\n\nIn the end, we had to spend a second extremely uncomfortable night at this "motel," as the property manager refused to offer a refund.  Seeing that we had already paid for 7 rooms ahead of time (for 2 nights) through the travel agency, we had no choice but to stay another dreadful night.\n\nI rarely leave negative reviews, but I feel it’s important to be honest so other travelers—especially those expecting comfort or celebrating a special occasion—can make an informed decision. This property did not meet basic expectations for comfort, maintenance, or guest care.','\n',char(10)),'Carla M. Casas',1);
INSERT INTO Review VALUES('1817525a-de90-4bdb-9067-4d36e8482ae5','a079c2fa-7503-4c97-80dd-c11337187217','Tolles privatgeführtes Hotel. Zu Empfehlen!','Ksenia Ryklin',5);
INSERT INTO Review VALUES('88eeaacb-139c-4760-8d20-6b082432720f','a079c2fa-7503-4c97-80dd-c11337187217','Fantástica  , pessoas e proprietários educados e gentis.','Robson Roberto Leandro',5);
INSERT INTO Review VALUES('50a18de9-4565-40e4-a828-0b7e8f14dc37','8be35984-a991-48c6-bc20-5a23aa7646c6','Beautiful place and service!!','Jessica Kim',5);
INSERT INTO Review VALUES('55857fde-5a99-4f44-b3e2-e97cb943223f','8be35984-a991-48c6-bc20-5a23aa7646c6','Amazing service and a wonderful experience. Thank you, Katherine.','Chellagurkhi Manjunath',5);
INSERT INTO Review VALUES('c2891355-7feb-452e-94db-a8537e6d88a0','9f78b4ad-04e0-4871-accb-8c1c35d376a3',replace('I booked a night at Las Qolqas EcoResort in Ollantaytambo to explore the area before starting the Inca Trail, and it delivered exactly what I was hoping for.\n\nBefore arrival, the resort reached out to organise a pickup from town, which made things simple. On arrival I was welcomed with a drink, checked in promptly, and given time to sit and take in the gardens before being shown around the property and escorted to my room. The staff explained all the amenities clearly, and I liked that each tent or suite is themed around the flower that surrounds it.\n\nThe room itself is well suited to a solo traveller or a couple. There is a private deck at the front with sun chairs overlooking the gardens and surrounding mountains. Inside, the bed was comfortable and the tent was well equipped with a heater and fireplace, which made it feel cosy without losing the eco feel. The bathroom was modern and well finished.\n\nThe setting is a standout. The tents are positioned along the river, surrounded by mountains and well maintained gardens, so it feels quiet and secluded without being far from town. I even had a hummingbird in the garden outside my tent, which added to the overall experience.\n\nI opted for the three course dinner on site, which was good and very filling. The portions are generous, so it is worth keeping that in mind.\n\nThe staff were consistently helpful and attentive throughout the stay, and that carried through to departure. They organised a car to get me to the train station earlier than their standard schedule, and because I was leaving before breakfast they prepared a takeaway breakfast pack, which was a practical and appreciated touch.\n\nOverall, this is a well run eco resort in a strong location with a peaceful setting and thoughtful service, and it works very well as a stop before or after the Inca Trail.','\n',char(10)),'Discover with Daroy',5);
INSERT INTO Review VALUES('d74e741a-8cc2-4eda-8ec6-cfd893ee6131','9f78b4ad-04e0-4871-accb-8c1c35d376a3','Nice but very overpriced. Know what you are getting - there is a spa, with sauna; but it must be reserved, and only one person/room can reserve by the hour.  And of course, you can''t reserve before you arrive! So forget about using it, practically speaking.  Dinner is pretty good, but again, know there is nothing 5 star happening here. Rooms are tents, nice but small - the 8 bed tent has little room to stand up. Well located and really pretty location. But grossly overpriced for what you get. Nowhere near the quality of service or facilities for the price. Very Peruvian in that regard. As an update - hot water is solar powered - so shower before 8 PM or do without.','Sidney Silhan',3);
INSERT INTO Review VALUES('5611e2ef-3918-412b-8d6a-0b9091715746','9f78b4ad-04e0-4871-accb-8c1c35d376a3',replace('An exceptional resort experience from start to finish. The entire property was immaculate, with every detail thoughtfully maintained, and the level of service was truly impeccable. It felt like a perfect blend of comfort and luxury.\n\nAfter completing the 4-day Inca Trail, this was the ideal place to relax and recharge. The on-site spa was a highlight, offering a much-needed moment of recovery, and every meal I had was absolutely outstanding—beautifully prepared and full of flavor.\n\nI would highly recommend this resort to anyone looking for a luxurious and restorative stay.','\n',char(10)),'Robin McFall',5);
INSERT INTO Review VALUES('0f6b981d-79e2-431b-9adf-023602f3333e','b8f81c8f-3294-4a18-a7cd-8aa1ea3264f8',replace('Updated March 2026: I’ve been traveling with Heart of Travel (HoT) since 2022, and through their small-group tours I’ve experienced incredible places including Guatemala, Cuba, Ecuador & the Galápagos Islands, Colombia, and Mexico City. I''m super excited to be headed to El Salvador and back to Guatemala later this year!\n\nHoT truly understands how to create meaningful travel experiences filled with magic, joy, and genuine connection. Before joining HoT, I was a solo traveler. Their thoughtfully curated itineraries, intimate group sizes, and exceptional local guides, who bring deep passion and knowledge of their countries, have completely changed how I travel. HoT has turned me into a group traveler in the best possible way.\n\nWhat truly sets HoT apart is their deep respect for and commitment to the local communities they partner with. Their approach to sustainable travel goes far beyond buzzwords. They intentionally take travelers off the beaten path, creating opportunities to connect with people, culture, and everyday life while ensuring that tourism directly benefits the local communities who make these experiences possible. I am so thankful that I found Heart of Travel!','\n',char(10)),'Angelina Parker',5);
INSERT INTO Review VALUES('9218a0c8-452b-4ccc-b06a-1af6f399e1cf','b8f81c8f-3294-4a18-a7cd-8aa1ea3264f8',replace('This trip totally exceeded my expectations! I had never taken a group trip with strangers before, but with the uncertainty of travel in Cuba, this was a solid option to explore the island. I''m so grateful I went and didn''t put it off (November 2025)! The situation in Cuba has changed so quickly.\n\nWhile in Cuba, I felt safe the whole time, catered to by Paloma, Yeni, Pablo and the other kind and welcoming guides we had taking care of us. The group of travelers were also really fun and interesting people, many of whom I still am in touch with.\n\nSince I usually travel on my own, I usually cut corners, but on this trip the food was amazing, the lodging was fancier than I expected and there''s no complaining about traveling the entire time in classic cars. The amount of down time to rest and explore individually was perfect and I there was flexibility if we needed it. I could get used to this kind of a trip an 1000% would do it again :)','\n',char(10)),'Molly M',5);
INSERT INTO Review VALUES('5807398a-086d-4653-9eaf-0e2ce35fa930','b8f81c8f-3294-4a18-a7cd-8aa1ea3264f8','This travel company is special. After only one trip with them they already feel like family. The customer service is excellent- extremely receptive and responsive. The inclusions on the trips are amazing- you literally don’t have to worry about anything but enjoying yourself. I highly recommend and can’t wait for my next trip.','Stephanie Ripps',5);
INSERT INTO Review VALUES('29a19e3b-0f5b-41d8-9741-d9b4ee1b66c9','8f2f473c-b1dc-4ab7-a6c3-7e484001d97a',replace('The tour was overall fantastic. Roger was exactly the kind of guide we were looking for: a serious, highly professional, and dedicated leader who exceeded all our expectations. It is rare to find someone with his level of expertise and passion; he was undoubtedly the best guide we encountered during our two-week journey in Peru.\nWe particularly appreciated how the itinerary was managed. The tour was structured exactly as we wanted, allowing us to dedicate the right amount of time to each site. We never felt rushed, and we truly valued avoiding the typical ''hit-and-run'' tourist approach.\n\nAdditionally, our driver Mario was excellent—always professional, kind, and polite.\n\nWe rate this tour a 5/5 (Amazing).','\n',char(10)),'Alessandra Frulloni',5);
INSERT INTO Review VALUES('eceb5d99-3036-4c5e-b68d-a13e8bd80e0f','8f2f473c-b1dc-4ab7-a6c3-7e484001d97a','A one of a kind private city tour with an amazing driver and very educational tour guide. This private tour is highly recommended','Luis Leon',5);
INSERT INTO Review VALUES('207ed19f-7f7e-42ab-a25f-6745f3f5e5b5','8f2f473c-b1dc-4ab7-a6c3-7e484001d97a','We had a wonderful 3 days trip to the Sacred Valley and Machu Picchu. Both the guide (Anthony) and the driver (Michael) were very good and did the absolute best to make the trip memorable. The veichle was very comfortable and the 3 days well planned with sufficient time for each one of the site visited. I would recommend this.','Carlo Buccisano',5);
INSERT INTO Review VALUES('2b01eebc-c1a3-4343-9cfd-3bd1c4facc0b','ce46399e-a96c-4f32-b077-e630faffc4eb','Amazing tour climbing in sacred valley. The guides were fantastic! Highly recommend this tour company.  We had a blast!','Amanda P',5);
INSERT INTO Review VALUES('c050a561-8264-42b6-bad9-d7d38aff5346','ce46399e-a96c-4f32-b077-e630faffc4eb','En cada rincón algo de magia !! Excelente organización y puntualidad para las excursiones con maravillosos guías. Agradecimiento especial por la calidez en el trato y el contacto permanente con nosotros para cualquier necesidad.','Pato Manduca',4);
INSERT INTO Review VALUES('401d2172-31cd-45f1-8839-c9f1a72a5ad7','ce46399e-a96c-4f32-b077-e630faffc4eb','Son muy claros con las indicaciones, la organización del paquete, viajé sola pero en todo momento me sentí segura y acompañada.','Angelica Alfonso',5);
INSERT INTO Review VALUES('9a335227-b669-4eb6-a0af-dfe0d0665809','18535dd9-e632-4d61-bec5-05615ada6b62','Thank you so much for an excellent horse ride through the Sacred Valley - we loved it so much & Hubert has been excellent and told us a lot about the Inca history. Thank you!','Markéta',5);
INSERT INTO Review VALUES('1f974d4a-caf0-49bd-998a-c86ccab472ef','18535dd9-e632-4d61-bec5-05615ada6b62','It was a perfect day for exploration and adventure. Being in the midst of the rainy season, I booked last minute and they accommodated me! It was a private ride to the Pumamarka site, totally worth it! Views are stunning. Being a horse enthusiast myself, I was able to join Jacinto pre-trip to meet the horses out in the field, this was the most memorable moment of my travels, I loved all of it!','Andean Horse',5);
INSERT INTO Review VALUES('4ebddc63-d8d5-46ac-b040-7b5793d5be5d','18535dd9-e632-4d61-bec5-05615ada6b62','I love and support what Lindsay is doing to ensure that the locals benefit from tourism and not be exploited. We had a lovely 3 hour ride past the thousand terraces and along the rushing creek. We stopped for healthy snacks of tamales and a variety of fruits before heading back down.','KIM HECKMAN',5);
INSERT INTO Review VALUES('daaf87cf-8e57-473b-b52f-aea8347b32ec','f80f0e15-eafe-46d2-9577-1c832f244497',replace('Passamos dois dias com o Eddy pelo Vale Sagrado.\n\nAlém das incríveis experiências de aventura, feitas no hotel Vertical Sky, também tivemos a oportunidade de fazer um Pachamanca com toda a tradição local.\n\nNos dois dias de passeio visitamos as ruínas e locais tradicionais, porém alcançando lugares que os turistas não costumam ir, passeando por caminhos Incas, conhecendo a história do ponto de vista de um guia local.\n\nRecomendo muito a empresa, tanto para as aventuras (tirolesa, ponte e via ferrata), quanto para o serviço de guia.\n\nSe tiver tempo agende a experiência do Pachamanca, foi realmente muito especial.','\n',char(10)),'Giulia Lodi',5);
INSERT INTO Review VALUES('7ee56456-8f72-4627-8d2c-61c813ccbe71','f80f0e15-eafe-46d2-9577-1c832f244497','Toda la información está en su página. Pero no los precios y demoran en comunicarse','Ale Muñoz',4);
INSERT INTO Review VALUES('8be72aee-6057-4be1-82ad-4777482d3a93','f80f0e15-eafe-46d2-9577-1c832f244497','Amazing adventure!! Personalized zipline with gr8care..our family had the best time..overlooking beautiful mountains and Ollantaytambo town and station','Amit G',5);
INSERT INTO Review VALUES('a811ae86-1ae6-4c97-9cc6-befbccd9547b','0ec88ff6-0fe5-406c-a6e9-1b65f7960004',replace('This tour was the highlight of our 8 day trip to Peru. My kids liked it more than anything else we did in Lima, Paracas, or the Sacred Valley.\n\nPepe and Mario were excellent hosts. They made us feel safe and confident driving the ATV''s despite having no prior experience.\n\nThe scenery was breathtaking, the price was affordable, and the sites were stopped at were beautiful. At the end of the trip, my kids were begging to ride a few more miles.\n\nIf you are looking for an ATV tour in Peru, this is a no brainer!\n\nThank you Mario and PePe!','\n',char(10)),'James Storie',5);
INSERT INTO Review VALUES('17532108-1db2-4ac8-87e8-d992781b508d','fd1c46fe-a33d-4449-9db5-878327c9b6ce','The most beautiful spontaneous experience! Hubert and his family are so lovely. I was invited to have breakfast with them and then Hubert offered me to meet his Lamas and feed them. He also offeres travel experiences in the Sacred Valley. I can really recommend booking with them. This has been one of my sweetest memories traveling through Peru 🫶🏽','M. K. B.',5);
INSERT INTO Review VALUES('b5ef55b8-a743-4a56-9a46-8cac852c9d86','fd1c46fe-a33d-4449-9db5-878327c9b6ce','Hubert took my wife and I on a tour of the Sacred Valley. We visited Chinchero,Moray and the Salt Mines of Maras. The whole day was excellent! Hubert was informative and was interested in any questions we asked. It was a well paced day.It was the best day trip we''ve had so far in Peru','Peter Jocham',5);
INSERT INTO Review VALUES('a23fe9af-79be-472e-8876-fae0867e9142','fd1c46fe-a33d-4449-9db5-878327c9b6ce','Tuvimos una excelente experiencia con Hubert,  como guía y transportista nos dio un servicio profesional! Lo recomiendo muchísimo es una persona profesional con una gran paciencia y también con un conocimiento extraordinario de la historia inca! Gracias Hubert!','Regina Zacke',5);
INSERT INTO Review VALUES('6d145258-ba01-44d8-8457-222135a104be','35907668-915d-4fed-87f5-47b27be1afc1','José is very friendly and professional.','Quentin Le Calvez',5);
INSERT INTO Review VALUES('edb98d8e-c895-4c00-bffa-94c042c8a4f5','35907668-915d-4fed-87f5-47b27be1afc1',replace('The best experience we had on a group trip we went with Ortiz Adventure to the Inka Avalanche competition, an epic competition full of adrenaline and living culture sharing with friends from different parts of the world.\nThe best service and with all our trip well organized.','\n',char(10)),'Ollanta Extremo',5);
INSERT INTO Review VALUES('db3e78a1-baf4-4ea2-8d24-4757c3fc24dd','35907668-915d-4fed-87f5-47b27be1afc1',replace('We hired 2 bikes for 2 days and rode down the Sacred Valley and back. Was a great adventure.\nWe did most of the communication on whsttapp before arriving in Ollantaytambo and all was very good.\nThe bikes were really good and the front suspension excellant for the bumpy back roads.\nGreat company and would definitely use them again.','\n',char(10)),'Nigel Hogarth',5);
INSERT INTO Review VALUES('1c62e520-eb11-449a-a0e6-201957f9ecf0','48e5da7c-4e7a-4a38-ab4e-519e9dfb0681','Thank you Ronny for a great day trip around the Sacred Valley. Ronny is knowledgeable and explained everything with enthusiasm.  He knew most people we passed by on the day, which shows his vast expertise and network. He took great photos, made yummy restaurant recommendations and helped us organise transport for the next day - we really appreciated the authentic and local experience.','Dori',5);
INSERT INTO Review VALUES('7d838b56-9ec5-4666-b2e2-41860f337ca8','48e5da7c-4e7a-4a38-ab4e-519e9dfb0681','Ron is very knowledgeable on the history of Inca and patient in explaining the attractions. Would recommend','Kuo Jixiang',5);
INSERT INTO Review VALUES('22c0d737-b4e0-4951-abce-413d6360daa1','48e5da7c-4e7a-4a38-ab4e-519e9dfb0681',replace('Ronny, the man, the myth and the legend did not disappoint. We did the Ollantaytambo ruin tour with Ronny, and he was extremely well read, knowledgeable and experienced as a tour guide. His passion for the history of the region was far above and beyond what I had expected from a guide. We would not have learnt as much about Ollantaytambo ruins and the town itself without his explanation.\n\nThroughout the tour, Ronny spoke in excellent English and was extremely friendly. Again, he blew our expectations out of the water. He was professional, knowledgeable and soon became a great friend. For those skeptical of the agency and how they don''t have a website and are Whatsapp only (like us, initially) ... look at all these positive reviews that have been left. They do not lie. Book a tour with Ollantaytambo Explorer. You will not be disappointed.\n\nThank you Ronny for the amazing experiences!!','\n',char(10)),'Harry Lau',5);
INSERT INTO Review VALUES('2066633c-ae56-41d8-9434-b5c53aedba2e','1971c8ab-d542-4042-9d9c-413742de12a4',replace('This place is acceptable but one can definitely do better.\n\nI arrived on a Friday when there was a weekend-long festival in town. Many places were booked up and this does sport a convenient location with an admittedly beautiful terrace, so hey.\n\nThe rooms seem overpriced for what it is. I was on the third floor and wifi was basically unusable most nights. Even the cellular data I purchased for my phone was poor within my room, but fine outside of it.\n\nThe restaurant was strange. Rarely opened for breakfast. I tried to get dinner there once and ordered three things. The one thing that came was delicious but after waiting for almost an hour I gave up on the other two things coming.\n\nThe room didn’t seem overly clean. I noticed some remnants of other guests (half used shampoo packets) and general dirt/debris in places as well as a sticky floor.\n\nFor a small town Ollantaytambo is oversaturated with places to stay. In all honesty I would definitely stay elsewhere if I was ever back.','\n',char(10)),'JD',2);
INSERT INTO Review VALUES('d783cf72-f6d6-476c-b316-385001a59e88','1971c8ab-d542-4042-9d9c-413742de12a4','Perfecto lugar para descansar. Buena relación calidad-precio. Amabilidad. Habitación cómoda. Terraza con espectaculares vistas de ese lugar tan mágico. Buenísima la comida de su restaurante.','David Namaste',5);
INSERT INTO Review VALUES('133254c5-70d3-47b0-8add-413102157da9','1971c8ab-d542-4042-9d9c-413742de12a4','Muy bueno. Acogedor y buen servicio. Muy amables. En el centro de Ollantaytambo','Jimena Salazar',5);
INSERT INTO Review VALUES('5c88a334-047b-49b3-90f6-d39cff2cd15e','9328824e-ee9d-4cf9-a6ed-1126616712cf','Carlos is an excellent guide - we went riding across the valley and it was amazing! Highly recommend!','Balint & Natasha',5);
INSERT INTO Review VALUES('e322135f-d540-4919-98dc-94d58d3f3dab','9328824e-ee9d-4cf9-a6ed-1126616712cf','We took the horseback riding tour.  It was amazing. A little scary sometimes since we were right on the side of the cliff.  Great views, I would highly recommend it.','Chantal Menard',5);
INSERT INTO Review VALUES('2da91f0f-9e3e-4d47-92c5-6b62e40e4930','9328824e-ee9d-4cf9-a6ed-1126616712cf','Had an amazing cabalgatas / horse riding trip with Félix. Best value I found in Ollantaytambo and very beginner friendly. Great way to see the nature outside the town.','Daisy Williams',5);
INSERT INTO Review VALUES('7e13ac84-5dae-4e9c-b4fd-29eec8fbdff9','7820c566-f5b3-4f9f-8770-90a7d7b39680','Servició perfecto gracias 💘💘💘💘🏔️🏔️🏔️🏔️','Grainne Hutcheson',5);
INSERT INTO Review VALUES('0ad89808-b185-46fb-a195-266cb3f0b6ab','7820c566-f5b3-4f9f-8770-90a7d7b39680','If I could give Naydu 10/5 stars, I would. My mom and I spent the day traveling from Ollaytantambo to Cusco and it was literally my favorite day in Peru. We felt so comfortable and safe with him and his driving, and we thoroughly enjoyed our time spent with him. His knowledge of history and storytelling left us with no question unanswered; we learned so much and he took us to such beautiful historic places. He was also so accommodating and respectfully suggested tweaks to our itinerary so we could make the most of the day. I think everyone should include a day with Naydu in their Peru trip!!','Elyssa Hernandez',5);
INSERT INTO Review VALUES('d34cbcca-b0b7-4ae9-a389-1b9e1bc35c0f','7820c566-f5b3-4f9f-8770-90a7d7b39680',replace('Nous avons passé une super journée à la découverte de la vallée sacrée.\nNous étions accompagné par Naydu, très gentil, souriant, attentionné et de bons conseils.\nLa voiture était très confortable.\nNous nous sommes sentis en sécurité.\nNaydu nous a également amené dans un très bon restaurant le midi.\nNous recommandons !!!\nAlice et Florian','\n',char(10)),'Florian Exbrayat',5);
INSERT INTO Review VALUES('5e9c13de-0124-4642-b4a2-37e43e9226d3','024ef7cd-def5-4057-b9f4-e4da62a099d1',replace('Wir haben mit Ernesto eine Tour durch die Ruinenstätte in Ollantaytambo gemacht und waren rundum begeistert. Er hat sich viel Zeit genommen und man hat sofort gespürt, wie sehr er für das Thema brennt – das war wirklich erfrischend.\n\nStatt uns einfach „durchzuschleusen“, wie man es bei vielen großen Gruppen beobachten kann, hat Ernesto alles ruhig und verständlich erklärt. Dabei hat er unglaublich viele spannende Details vermittelt – genau die Art von „Klugscheißerwissen“, die eine Führung erst richtig besonders macht.\n\nDie Tour war jeden Cent wert und wir können ihn uneingeschränkt weiterempfehlen. Vielen Dank, Ernesto!','\n',char(10)),'T KS',5);
INSERT INTO Review VALUES('b1cb58aa-447d-4899-9094-7a090463f81e','024ef7cd-def5-4057-b9f4-e4da62a099d1',replace('Ernesto hat uns zufällig am Eingang der Inka-Stätten in Ollantaytambo angesprochen und uns seine Nummer gegeben, da wir zu dem Zeitpunkt keine Zeit für eine Führung hatten. Am nächsten Tag sind wir spontan vorbeigegangen – ohne vorher Bescheid zu sagen. Er war nicht da, kam aber nach unserer Nachricht innerhalb weniger Minuten extra für uns zurück. Das fanden wir wirklich bemerkenswert.\n\nDie Tour selbst war sehr individuell und angenehm ruhig, obwohl viel los war. Ernesto hat alles so gestaltet, dass wir genug Raum hatten, Fragen zu stellen und die Orte in Ruhe zu erleben. Sein Wissen ist beeindruckend und er erklärt alles verständlich auf Englisch.\n\nBesonders schön war zu merken, wie sehr er für die Inka-Kultur und die Berge brennt – das hat die Führung wirklich besonders gemacht. Er hat sich viel Zeit genommen, uns auch weniger besuchte Bereiche gezeigt und nebenbei tolle Fotos von uns gemacht.\n\nAuch danach war er noch erreichbar und hat uns bei Fragen weitergeholfen – absolut nicht selbstverständlich.\n\nKlare Empfehlung: Wenn ihr in Ollantaytambo seid, fragt nach Ernesto – es lohnt sich!','\n',char(10)),'Ola',5);
INSERT INTO Review VALUES('b3995c78-794e-4e72-b569-2a5f0ec38303','024ef7cd-def5-4057-b9f4-e4da62a099d1','Hemos hecho el tour completo de Ollantaytambo con Ernesto y ha sido la mejor decisión que podríamos haber tomado! Súper amable, profesional, ha respondido a todas nuestras dudas. Se conoce bién el lugar y ha compartido con nosotras toda su sabiduría. Totalmente recomendable!','Natalia García Verjano',5);
INSERT INTO Review VALUES('8984baa1-3b28-4973-9d17-6df0dd17b433','877348b7-cebf-44c7-8f21-dcdc70b91afa','Wir haben zu zweit eine Tagestour zu Pisaq, Moray und den Salzminen Maras gemacht. Unser Guide war super nett. Er hat uns sehr sehr viel erklärt und viele Fragen beantwortet. Das Tempo der Tour war super angenehm, nicht zu schnell und nicht zu langsam. Wir konnten jederzeit auf dem Weg anhalten oder stoppen. Der Guide hat viele schöne Fotos von uns gemacht. Wir würden jederzeit wieder eine Tour bei der Agentur bzw. dem Guide buchen. Wir waren begeistert und hatten einen tollen Tag!','Cosima Göldner',5);
INSERT INTO Review VALUES('7229e485-b4e2-4b41-aa3d-a049b6a93e9d','877348b7-cebf-44c7-8f21-dcdc70b91afa',replace('Pasamos un día increíble con la agencia MARAS MORAY TOURS   un excelente tour privado todo estubo bien organizado el mejor guía  se notaba la experiencia y profesionalismo un lugar facinante y maravilloso los andenes de moray son impresionantes.\nExcelente servicio muy recomendable\n!!!','\n',char(10)),'rodrigo quispe',5);
INSERT INTO Review VALUES('59b8fa94-12ec-4370-90d0-3e21085c14a5','877348b7-cebf-44c7-8f21-dcdc70b91afa','We just returned home to Colorado USA and are so glad we chose Ruben and Maras Moray Tours. We had a fantastic experience on the Short Inca Trail and Sacred Valley tour with Ruben and driver Carlos. In the Sacred Valley, we visited Chinchero, Maras, Moray, and Ollantaytambo, with plenty of time at each stop and informative context to match the beauty of the sites. The Short Inca Trail and Machu Picchu were unforgettable, with Ruben pointing out great photo spots and sharing fascinating history. They booked all our Machu Picchu circuit reservations at ideal times—something we never could have navigated on our own. The accommodations they arranged suited us perfectly, they were always on time, and they provided excellent advice for the rest of our travels. We’re grateful to Ruben and his team for making this trip one we’ll always remember. If we return to Peru (hopefully!!) we will not hesitate to book this company again.','Ashley Prentice',5);
INSERT INTO Review VALUES('6a354012-facb-4f7e-8e96-5600bc3cf3ba','af83773a-e9af-4c03-8a00-8ac30ed8d532','Un demostrado de técnicas indígenas muy bonito. Comprábamos muchas regalos de alta calidad aquí','R. Ebrahim',5);
INSERT INTO Review VALUES('7af4311e-5e9a-4e58-aad6-8fd7379781f1','af83773a-e9af-4c03-8a00-8ac30ed8d532','Se encuentra en Chincheros, este lugar muy acogedor y nos explica sobre la artesanías textil Inka que se conserva de padres a hijos  hasta la actualidad. También puedes comprar y te dan a degustar muña planta digestiva.','Jacky Alfaro Bazan',4);
INSERT INTO Review VALUES('2c00e06d-8ceb-4ca0-b9bf-a67e37891a50','af83773a-e9af-4c03-8a00-8ac30ed8d532','Todo esta hermoso, pero hay que poner atención, porque hay textiles tradicionales y de materiales sintéticos, lo tradicional es caro, pero también refleja tradición, el esfuerzo de manos artesanas y es menos agresivo con la naturaleza.','Irene Fuerte',5);
INSERT INTO Review VALUES('470fbbf7-973c-48e1-a1a9-b7826cac5f2a','fecd0af2-145e-4b89-9828-fb51c9849727',replace('Je vous conseille fortement d''acheter vos pulls ici. Elles vous expliquent comment ils sont faits, les significations des dessins et plein de choses.\n\nEt tout ça gratuitement et avec le sourire.','\n',char(10)),'Maxime Taton (Maxime Taton)',5);
INSERT INTO Review VALUES('7ad571db-1d8a-4d08-8caf-01f1ac91f3b1','fecd0af2-145e-4b89-9828-fb51c9849727','Un sitio de artesanos. Tienen exposición de como hacen las diferentes tinturas y el proceso. Tienen una muestra grande de textiles','Ricardo Uribe',5);
INSERT INTO Review VALUES('cc0c878f-243c-45e9-8650-10b5abb03c7f','82a3794a-d392-4a31-85db-49bf14d0ff72',replace('Yes, this is definitely a spot designed for tourists, but it’s actually well worth the stop. We spent over an hour here and our group really enjoyed it.\n\nThe demonstration of the weaving and dyeing process is fascinating. They showed us live how they use parasites (cochineal) to create vibrant red dyes, and how adding something as simple as lemon juice changes the acidity to create yellows and oranges. It’s a great hands-on way to understand local traditions.\n\nOf course, there is a shopping area at the end, but the staff were not pushy at all. They give you the space to look around, and the prices are quite reasonable compared to other places. If you want to learn about the history behind these beautiful textiles without feeling pressured to buy, this is a great place to visit.','\n',char(10)),'Pazu P',5);
INSERT INTO Review VALUES('cff0b044-16f7-4c35-b8d6-ea3bce68e398','a1c12b76-63db-417d-a789-d0c482ec375b','Todos muy amables. Me encantó visitar este taller.','Lucía Papp-Zea',5);
INSERT INTO Review VALUES('64d77bcf-6478-43ee-9198-a014735d12f9','a1c12b76-63db-417d-a789-d0c482ec375b','Interesting info about how textile are made','Patricia Russow',4);
INSERT INTO Review VALUES('0224eb3e-1d75-4efe-87ee-67b7f7d94b3d','a1c12b76-63db-417d-a789-d0c482ec375b','Amazing presentation of Inka weaving! Great people presenting. They served up lunch of local specialties that was awesome!','Bob Ewing',5);
INSERT INTO Review VALUES('26e283aa-11c6-4579-bb49-995fd58bbe42','9f2e44a3-dc24-4ebd-8c52-d9a1ec71b226','I love experiencing the emergence of local animals, culture, food, and lifestyle—it’s like stepping into the soul of a place','M C',5);
INSERT INTO Review VALUES('567a9c42-0c35-40aa-95e6-c6cb10b4ee3b','9f2e44a3-dc24-4ebd-8c52-d9a1ec71b226','Lovely','1995CJ',5);
INSERT INTO Review VALUES('d91dbcc9-1526-4f4d-a997-24003fcdf293','9f2e44a3-dc24-4ebd-8c52-d9a1ec71b226','Amazing selection of handmade alpaca clothing etc, Corrie was very nice and explained the whole process of creating the textiles','Chris Robinson',5);
INSERT INTO Review VALUES('eb258e1b-0484-4d20-9bf4-be9a000144d0','afe1ed54-e0e0-4edb-9f50-2c3c6963f41d','Thank you Dacred Loom for my beautiful Mestana. It is so beautifully made & exactly what I asked for.  Thank you also in the safe delivery to my country. It was a positive experience & a pleasure to deal with you. ☺️🙏🏼✨','Gyalten Drolkar',5);
INSERT INTO Review VALUES('dfc9bb10-ac86-426b-863d-2cb287126149','afe1ed54-e0e0-4edb-9f50-2c3c6963f41d','I ordered a Messina from Sacred Loom as I am on a course about the way of the Queros, the Peruvian Medicine wheel, here in England and wanted an authentic cloth. The purchase was easy, the packet arrived quickly and I am very happy with my Mesa cloth. I can only recommend The Sacred Loom to anyone who is looking for a Peruvian Messina/Mesa cloth.','Simone Huber',5);
INSERT INTO Review VALUES('c9891c09-23b7-4b4c-91f7-ebe0f236a124','afe1ed54-e0e0-4edb-9f50-2c3c6963f41d',replace('So happy with this sacred mesa. I can feel and see  the love it was carefully made with.\nThank you so much.  Sending love and light.\nYour sister ,   Anny (from New Jersey  USA)','\n',char(10)),'steve marchioni',5);
INSERT INTO Review VALUES('e33e2926-4ddf-49ec-8386-2ff684c06c2b','c7fa33d0-404a-46c0-8f40-78d49975dda4','Excellent demonstration on weaving and very friendly hostesses!','Amy Emerson',5);
INSERT INTO Review VALUES('ff8a595d-fb39-4857-8a0c-ee2e9cc979b3','c7fa33d0-404a-46c0-8f40-78d49975dda4','Ottimo posto poter fare gli acquisti di Chinchero   dove potete trovare i migliori materiali della regione di Cusco. Mariluz potrà fare una esauriente spiegazione delle colorazioni e della  tessitura.','Fabiano',5);
INSERT INTO Review VALUES('3a5beda0-1ee4-4367-ae47-934222608107','c7fa33d0-404a-46c0-8f40-78d49975dda4','Interessante anche se tutto finalizzato alla vendita :-(','Andrea Loli',5);
INSERT INTO Review VALUES('84e95032-4d58-4350-b900-6e5ad0e87e8f','1444ae8e-5df6-4331-a423-a22e9679e51d','친체로에 있는 민속 마을이다. 해발 3700m정도이고 쿠수코에서 30~40분 정도 떨어진 마을이고, 현재 쿠스코 신 국제공항이 건설되고 읶는 곳이다. 마을 뒤쪽에 오래된 집들과 돌로 잘 만들어진 계단이 있는 오래된 마을이 나타났고, 더 올라가고 싶었지만 고산증이 나를 그 계단에만 머물게 했다. 계단을 내려가니 민속마을 안내 설명이 있었고, 그 앞에는 주차장과 화장실 유로 가 있었다.','안병하',5);
INSERT INTO Review VALUES('cc33c9c9-b0a6-4fc0-b5e6-b4d43f4cbf6e','6e515551-3107-4031-8174-1afb15ce4c9d','En una palabra Maravillosa','José Luis Pacahuala',5);
INSERT INTO Review VALUES('0400a86b-90ee-4f03-bb41-443c9c95a11f','aa3cc48d-e07f-49f0-b5a5-362ada6e9f4f','This was a tourist trap and a deeply disappointing experience. I was charged nearly 3x the prices I later found for similar or better quality items throughout Peru. I felt misled and taken advantage of as a tourist. Based on my experience, I would strongly caution others to compare prices carefully before buying here.','kawtar douidy',1);
INSERT INTO Review VALUES('e7d0be3b-ccbb-479e-9133-a7f7d9a6eb92','aa3cc48d-e07f-49f0-b5a5-362ada6e9f4f','This was one of the excursions that I was really looking forward to because I am a hand crafter. The presenter was hilarious and engaging. It was a wonderful tour of the entire process from the gathering of the wall from the animals to the processing of the wall to the actual making of products for sale. There is a shop where items can be purchased because they are handmade. They are on the higher end of the price tag, but they did have items for multiple levels of price.','Cynthia Ford',5);
INSERT INTO Review VALUES('dd08d41c-cc0a-4f65-b79e-a4208e97f8f5','aa3cc48d-e07f-49f0-b5a5-362ada6e9f4f','Un buen lugar para conocer de cerca costumbres y tradiciones ancestrales de la época inca.','aventurperu Ventas',5);
INSERT INTO Review VALUES('6b637de3-e396-4be1-b9ab-c81af5c774a6','4999b0ca-8698-43af-bcdd-9a11a995d9de','They explained the process very very well. They also explained how to make different colors. Their products are very high quality and you should definitely come here.','Shraddha Shah',5);
INSERT INTO Review VALUES('2f60d140-90d6-4d06-90cf-9c3088a68b2d','4999b0ca-8698-43af-bcdd-9a11a995d9de','Muy completa explicación, gente grata y muy buenos productos.','Luciano Pistacchia',5);
INSERT INTO Review VALUES('de7eaee8-457e-4848-a7a3-decc01d6bf83','4999b0ca-8698-43af-bcdd-9a11a995d9de','Luga3 genial para comprar','Beto Núñez',4);
