INSERT INTO Review VALUES('e8062543-c5d1-4d74-bb6a-fd2793a26705','363aabf4-291c-45e0-99b5-0bee9cd42b6f',replace('Muy rico el menú, saludable, balanceado y colorido. Muy bien presentado.\nEnseñan a alimentarse bien a los comensales que lo solicitan. Preparan su carne de gluten y el tofu con soya orgánica de la zona.','\n',char(10)),'Google Reviewer',5);
INSERT INTO Review VALUES('9983a592-852e-496b-90a2-d63fb29d6c7f','363aabf4-291c-45e0-99b5-0bee9cd42b6f','Una sopresa molt agradable! El menjar més bo i més saludable que he menjat a Perú. Na Juliet és un amor de persona i cada dia prepara uns menús vegetarians deliciosos, si passes per Urubamba has de provar el seu menjar.','Google Reviewer',5);
INSERT INTO Review VALUES('3465c9f7-005d-4980-8ed8-89491770dcba','634747c8-0210-474b-837b-32160bd936af','The restaurant has a really nice ambience and also a versatile and creative menu. The food was good, nothing mind blowing but good. The service was a bit slow though, which was surprising since we arrived there quite early before there were any other guests.','Google Reviewer',4);
