INSERT INTO Review VALUES('ec48d727-1eef-42b0-9251-a3dd2bf3e6d9','802624bf-3a8d-4bbb-be43-fe7b84a97472','Split a couple of dishes with my wife here for lunch.  The food was spectacular - beautifully presented, and well seasoned.  Our waitress Claudia was an absolute delight, and as soon as my wife mentioned wanting to share Claudia took initiative and brought the dishes out split into separate dishes.','Google Reviewer',5);
