INSERT INTO Review VALUES('4b42505e-e6f2-4044-ae9f-acb9b2cb7dda','802624bf-3a8d-4bbb-be43-fe7b84a97472',replace('Todo excelente, todos los sabores muy pronunciados, con un toque personal del lugar, todo muy rico.\n\nClaudia la chica que me atendió un 7, además de entregar una muy buena atención, entregó información muy buena de la localidad, recomendado al 100%','\n',char(10)),'Google Reviewer',5);
