INSERT INTO Review VALUES('faaebeb8-c09d-43d3-becf-2cf9278db7fc','475fe1c6-dbef-41ee-8c13-5e5d1db37bee',replace('I really enjoyed my stop at La Ventanita. I dropped in for a quick meal as I was passing through Urubamaba. The owner Frank prepared me a delicious breakfas, and tasty lemonade. We had a great conversation while I ate\nand the atmosphere of the cafe was very comfortable and accommodating. Highly suggest a stop here for a meal or coffee if you are in the area. I know I’ll be back!','\n',char(10)),'Google Reviewer',5);
INSERT INTO Review VALUES('bda8cf41-e6bd-4e54-8a13-a3c40780e2d3','475fe1c6-dbef-41ee-8c13-5e5d1db37bee','Quaint cafe close to Plaza de Armas. Frank, the owner, is very hospitable and attentive. They have a menu in English, which is very helpful, and free wifi.','Google Reviewer',5);
