INSERT INTO Review VALUES('80a8e0cb-c83d-4578-9d48-60b7574c8082','144d63d3-c745-45e4-91e3-e9f294d26008','Was a top noch café,  went recently after they reopened, food quality went way down..Roast Beef was stringy and chewy...Crispy Chicken Sandwich wasnt crispy not good taste ..side salad came dry with no sauce...waiters didnt come by to see if we wanted/ needed anything else until we where done...a dissapointment for a place that was one of the best in Sacred Valley','Google Reviewer',5);
