INSERT INTO Review VALUES('39f8fbcc-03ca-4da4-8196-9d20cf938009','01424206-6464-447a-bdb5-b16e3e0506e7','PAN CON CHICHARRÓN 10/10 excelente. Te lo preparan del momento, todo fresco, generoso Y delicioso. Vine buscando un desayuno criollo y este lugar me dio una experiencia deliciosa. Es la segunda vez que vengo y repetiría. Felicidades!','Google Reviewer',5);
INSERT INTO Review VALUES('62b6fa2f-9cbc-4431-88fc-98ac31cf523d','01424206-6464-447a-bdb5-b16e3e0506e7','We loved it here. The ice cream is so good! Fresh herbs used from their garden. Quiet and pretty environment. Peaceful owners.','Google Reviewer',5);
