INSERT INTO Review VALUES('b382e34c-09d6-4380-ad49-df77958214ea','01424206-6464-447a-bdb5-b16e3e0506e7',replace('Absolutely wonderful bakery with the best tiramisu I’ve ever had! It was perfectly fresh, creamy, rich, and balanced.\n\nThe staff were incredibly kind, welcoming, and attentive, which made the whole experience even better. They create such a warm and friendly atmosphere.\n\nThe bakery itself is beautiful, comfortable, and very versatile. I really appreciated the variety of seating options: outdoor tables, cozy indoor seating, as well as both high and low tables to suit everyone’s preference.\n\nHighly recommended!','\n',char(10)),'Google Reviewer',5);
INSERT INTO Review VALUES('f8e57b4d-0122-4a80-9835-3c7c9095753b','1f603ce4-231a-4a9a-b7c8-d68e0f0ff28f','Great find in Urubamba! Delicious, fresh, homemade falafel. Friendly service and chill vibe. Absolutely recommended.','Google Reviewer',5);
