INSERT INTO Review VALUES('4d535345-b306-4ee0-aeec-3db8a1634f4f','1f603ce4-231a-4a9a-b7c8-d68e0f0ff28f','Amazing place which is very close to Plaza. Lovely staff, incredible coffee and delicious food! Must try açai bowl and teriyaki chicken bao.','Google Reviewer',5);
INSERT INTO Review VALUES('4d8dd0f1-c853-4c29-bd2d-f6ab360e6aa3','1f603ce4-231a-4a9a-b7c8-d68e0f0ff28f','Best coffee in Urubamba! The food is tasty too. The quiet and spacious co-working room is perfect for a day of focusing on computer work.','Google Reviewer',5);
