INSERT INTO Review VALUES('19b1629e-33b1-473b-be8f-6d18d7d750f1','f00d8498-b524-4fb2-b68c-37bbc9f40a09','Yuri era un conductor muy confiable, y su coche está extremadamente limpio. Lo recomiendo mucho si quieres un recorrido agradable por el Valle Sagrado.','Google Reviewer',5);
INSERT INTO Review VALUES('93c5b6ff-e6e1-4a87-98e9-c9c1c8575bca','f00d8498-b524-4fb2-b68c-37bbc9f40a09','Yuri was incredible during our recent trip to the Sacred Valley! He was recommended to us by our Air BnB host and did not disappoint. He was quick to respond and added so much value to our travels. He was full of knowledge and gave us so much information on the rich history of the area. I can definitely recommend Yuri to anyone visiting the Sacred Valley ☺️','Google Reviewer',5);
INSERT INTO Review VALUES('aaddc0a7-594b-4452-9b15-f79e9efd0fba','f00d8498-b524-4fb2-b68c-37bbc9f40a09','Yury is one of the best driver. He is very friendly and always drives carefully. Highly recommended 👍','Google Reviewer',5);
INSERT INTO Review VALUES('8b1e70fc-f40f-449e-ad1f-8615da354a04','e78a88ae-6739-445b-914b-2e4516c91e7f','Fantastic services. We used Taxi Sacred Valley for all our transport needs including transfers and day trips. Their cars were great, drivers very kind & helpful and always on time. We used them for transfers from Cusco to Sacred Valley and for day trips to see the Moray, Moras, Ollantaytambo and Rainbow Mountain. They were will to pick up rides for us last minute and were very adaptable. We wouldn’t use anyone else. Highly recommend! Very responsive via WhatsApp.','Google Reviewer',5);
INSERT INTO Review VALUES('3909303f-f55a-4c13-82f5-ff27a455ef20','e78a88ae-6739-445b-914b-2e4516c91e7f','Great service! Would 100% recommend','Google Reviewer',5);
INSERT INTO Review VALUES('b984049a-ac49-44d0-b0c5-02623f53789e','e78a88ae-6739-445b-914b-2e4516c91e7f','Excellent services. We have used them many times and they have always been careful, punctual, and fun to ride along with! Saul was great on the trip from Cusco down to the valley. 100% recommend for the safest way to travel.','Google Reviewer',5);
INSERT INTO Review VALUES('95cb4009-6843-4a98-a740-5c5c032c4b01','e78a88ae-6739-445b-914b-2e4516c91e7f','We had a great experience in our tour. We did the sacred valley half day chincheros, maras and moray with wilfredo. He was excellent! Definitely recommend Taxi Sacred Valley. We felt safe and loved it!','Google Reviewer',5);
