INSERT INTO Review VALUES('903dd4b4-3203-4a6b-a397-436c04c50e11','7dc7f7ac-2f4a-4bda-a7c3-6f57eb245ddb','Una experiencia única,.la recomiendo al 100%','Google Reviewer',5);
INSERT INTO Review VALUES('6e3a1a8b-3ea0-4a1b-99c5-44b521d573c0','7dc7f7ac-2f4a-4bda-a7c3-6f57eb245ddb','Experience was just ok. Felt too rushed at the locations (eg. we were told we only had 25min to explore Moray after paying $20USD entry fee). We only spent an hour on the ATV’s riding from site to Moray and back (mostly on road, only some off road). Moray we went on the minibus. The company / guides are review hungry, our guide also asked us to write a review on the spot when we arrived at Moras (included in the 25min we had to explore the site, after anthor $5usd entry). Worry more about guest experience and the good reviews will follow ATV Cusco.','Google Reviewer',2);
INSERT INTO Review VALUES('9aac9c99-41e2-44b2-9455-03caefd6f2b5','b0ac1626-71b2-475d-82bd-4b4e99255181','Vistas espectaculares de su belleza natural','Google Reviewer',5);
