INSERT INTO Review VALUES('5331fb36-0f3d-4a16-9c1d-5e1b08301b84','b0ac1626-71b2-475d-82bd-4b4e99255181','Raul fue estupendo, todo estuvo bien seguro y nos llevo por dos caminos hermosos! Lo recomendaria 100% Una experiencia UNICA!!','Google Reviewer',5);
