INSERT INTO Review VALUES('8892c87c-a8ed-4b84-aa2e-dd82eabd081e','df109b53-06ed-4b86-a41e-7d911fe6088e','El recorrido fuè muy chevere y la atenciòn bastante buena, hicimos el tour de Zipline y Cuatrimotos!','Google Reviewer',5);
